// Loopy Knowledge Packs: answers written for Loopy Brain from standard textbook rules. Checked first, before any outside source.
// Fields: keys (phrases to match), title, short (exact definition), points, steps, formulas [name, text], example, exam, mistakes, uses [title, text], related, diag (text that picks Loopy's own diagram).
export const PACKS = [
  { id: "gates", keys: ["logic gate", "logic gates", "and gate", "or gate", "not gate", "nand gate", "nor gate", "xor gate", "universal gate", "universal gates"], title: "Logic gates", subject: "Digital electronics",
    short: "A logic gate is a circuit that takes one or more binary inputs (0 or 1) and gives one binary output according to a fixed rule.",
    points: ["AND gives 1 only when all inputs are 1. OR gives 1 when at least one input is 1. NOT flips the input.", "NAND is AND followed by NOT. NOR is OR followed by NOT. XOR gives 1 when the inputs are different. XNOR gives 1 when they are the same.", "NAND and NOR are called universal gates, because any other gate or circuit can be built using only NAND gates, or only NOR gates.", "Each gate is described by a truth table, a Boolean expression and a symbol.", "A buffer gives output = input. It only boosts the signal. A small circle on a gate output means complement.", "AND and OR can have many inputs. NAND and NOR are not associative, so a 3-input NAND is defined as (xyz)’ and a 3-input NOR as (x + y + z)’."],
    formulas: [["AND", "Y = A · B"], ["OR", "Y = A + B"], ["NOT", "Y = A’"], ["NAND", "Y = (A · B)’"], ["NOR", "Y = (A + B)’"], ["XOR", "Y = A⊕B = A’B + AB’"]],
    example: { title: "Two-input truth table (A, B → AND, OR, XOR)", text: "00 → 0, 0, 0\n01 → 0, 1, 1\n10 → 0, 1, 1\n11 → 1, 1, 0" },
    exam: "A logic gate is an electronic circuit that performs a basic logical operation on one or more binary inputs and produces a single binary output. The basic gates are AND, OR and NOT. NAND and NOR are universal gates because every other gate can be built from either one of them. The behaviour of each gate is shown by its truth table.",
    mistakes: ["Mixing up NAND and NOR. NAND outputs 0 only when all inputs are 1. NOR outputs 1 only when all inputs are 0.", "Forgetting that XOR is 0 when both inputs are 1.", "Thinking a NOT gate can have two inputs. It has exactly one."],
    uses: [["Phone and computer processors", "Billions of gates inside the chip make every calculation and decision."], ["Door and alarm systems", "AND and OR gates combine sensor signals, for example alarm = door open AND system armed."], ["Traffic and lift controllers", "Gates decide which light or floor comes next from the sensor inputs."]], related: ["Boolean algebra", "Karnaugh map", "Combinational logic"], diag: "" },
  { id: "boolean", keys: ["boolean algebra", "boolean laws", "de morgan", "demorgan", "boolean expression", "boolean function", "boolean theorem"], title: "Boolean algebra", subject: "Digital electronics",
    short: "Boolean algebra is the mathematics of two-valued variables (0 and 1) with the operations AND, OR and NOT. It is used to describe and simplify digital circuits.",
    points: ["Simplifying a Boolean expression reduces the number of gates, so the circuit is cheaper, smaller and faster.", "De Morgan’s laws let you swap AND and OR by complementing: they are the key to converting a circuit into NAND-only or NOR-only form.", "Every law has a dual: swap AND with OR and 0 with 1 and the law is still true.", "George Boole published the algebra in 1849. Claude Shannon showed in the late 1930s that it describes circuits built from switches.", "Order of operations: NOT first, then AND, then OR. You can prove any identity by perfect induction (a truth table) or by a Venn diagram.", "Handy results: x + x’y = x + y, x(x’ + y) = xy, and the consensus law xy + x’z + yz = xy + x’z."],
    formulas: [["Identity", "A + 0 = A,  A · 1 = A"], ["Null", "A + 1 = 1,  A · 0 = 0"], ["Idempotent", "A + A = A,  A · A = A"], ["Complement", "A + A’ = 1,  A · A’ = 0"], ["Double negation", "(A’)’ = A"], ["Commutative", "A + B = B + A,  AB = BA"], ["Distributive", "A(B + C) = AB + AC,  A + BC = (A + B)(A + C)"], ["Absorption", "A + AB = A,  A(A + B) = A"], ["De Morgan 1", "(A · B)’ = A’ + B’"], ["De Morgan 2", "(A + B)’ = A’ · B’"], ["Combining", "AB + AB’ = A,  (A + B)(A + B’) = A"], ["Useful", "A + A’B = A + B"], ["Consensus", "AB + A’C + BC = AB + A’C"]],
    example: { title: "Simplify F = AB + AB’", text: "F = A(B + B’)   ← take A common\nF = A · 1       ← B + B’ = 1\nF = A" },
    exam: "Boolean algebra deals with binary variables and the logical operations AND, OR and NOT. Its main laws are identity, null, idempotent, complement, commutative, associative, distributive, absorption and De Morgan’s laws. Using them, a logic expression can be simplified to need fewer gates. Example: AB + AB’ = A(B + B’) = A.",
    mistakes: ["Writing (A + B)’ = A’ + B’. The correct form is A’ · B’.", "Forgetting that A + AB = A (absorption).", "Cancelling terms like ordinary algebra. A + A = A, not 2A."],
    uses: [["Chip design", "Engineers simplify expressions so the chip needs fewer gates and less power."], ["Search and filters", "Search “phones AND NOT used” follows the same rules."], ["Programming", "if conditions with &&, || and ! are Boolean algebra."]], related: ["Karnaugh map", "Logic gates", "Combinational logic"], diag: "" },
  { id: "kmap", keys: ["karnaugh map", "k map", "kmap", "k-map", "karnaugh"], title: "Karnaugh map (K-map)", subject: "Digital electronics",
    short: "A Karnaugh map is a grid that shows a truth table so that neighbouring cells differ by only one variable. Grouping the 1s gives the simplest sum-of-products expression.",
    points: ["The cell order is in Gray code: 00, 01, 11, 10, never 00, 01, 10, 11.", "Group adjacent 1s in rectangles of size 1, 2, 4, 8 or 16 (powers of 2).", "Make each group as large as possible, and use as few groups as possible. Groups may overlap.", "The map wraps around: the left and right edges are neighbours, and so are the top and bottom edges.", "Don’t-care cells (X) can be treated as 1 only if they make a group larger.", "A 5-variable map is two 4-variable maps side by side; cells in the same place in both maps are neighbours.", "To get a product-of-sums answer, group the 0s and write a sum term for each group.", "Literals in a term: in an n-variable map, a group of 2ᵏ squares gives a term with n − k literals. In a 4-variable map: 1 square = 4 literals, 2 squares = 3, 4 squares = 2, 8 squares = 1, 16 squares = the constant 1.", "Squares are numbered by the binary number of row and column, in reflected (Gray) order, so only one bit changes between neighbours. Any such numbering is valid; maps drawn with other layouts (Veitch’s original, rows and columns swapped) work the same way.", "5-variable map = two 4-variable maps. The centre double line acts like a mirror: each square is also adjacent to its mirror image. For example, minterm 31 is adjacent to 30, 15, 29, 23 and 27. A 6-variable map = four 4-variable maps. Beyond 6 variables, maps are impractical.", "Example with both forms: F = Σ(0,1,2,5,8,9,10). Group the 1s: F = B’D’ + B’C’ + A’C’D. Group the 0s: F’ = AB + CD + BD’, so F = (A’ + B’)(C’ + D’)(B’ + D).", "Map history: Veitch proposed it in 1952 and Karnaugh modified it in 1953."],
    steps: ["Write the truth table or the minterms.", "Draw the map for the number of variables (2, 3 or 4) with Gray-code labels.", "Put 1 in each minterm cell, 0 elsewhere (X for don’t-cares).", "Circle the biggest groups of 1s (1, 2, 4, 8, 16 cells).", "For each group, keep the variables that do not change inside the group.", "OR the group terms to get the simplified expression."],
    formulas: [["Group of 2", "removes 1 variable"], ["Group of 4", "removes 2 variables"], ["Group of 8", "removes 3 variables"]],
    example: { title: "F(A,B,C) = Σm(1,3,5,7)", text: "The four 1s form one group of 4 (all cells with C = 1).\nA and B change inside the group, C does not.\nSo F = C." },
    exam: "A Karnaugh map is a graphical method to simplify Boolean expressions. The cells are arranged in Gray code so that adjacent cells differ in one bit. Adjacent 1s are grouped in powers of two (1, 2, 4, 8, 16) and each group gives one product term from the variables that stay constant. The simplified expression is the OR of all the group terms.",
    mistakes: ["Using binary order (00, 01, 10, 11) on the axes instead of Gray code.", "Making groups of 3, 5 or 6. Groups must be 1, 2, 4, 8 or 16.", "Forgetting the wrap-around groups at the edges and corners.", "Using a smaller group when a bigger one is possible."],
    uses: [["Designing control logic", "Engineers shrink the logic for a machine controller so it needs fewer chips."], ["Seven-segment displays", "Each segment’s on/off rule is simplified with K-maps."], ["Exam questions", "A very common 5 to 10 mark question in digital electronics."]], related: ["Boolean algebra", "Logic gates", "Combinational logic"], diag: "" },
  { id: "comb", keys: ["combinational logic", "combinational circuit", "combinational circuits", "combinational design", "combinational logic circuits"], title: "Combinational logic", subject: "Digital electronics",
    short: "A combinational circuit is a digital circuit whose output depends only on its present inputs. It has no memory and no clock.",
    points: ["It is built only from logic gates, with no feedback and no storage.", "The same inputs always give the same outputs.", "Typical examples: adders, subtractors, multiplexers, demultiplexers, decoders, encoders and comparators.", "A combinational circuit with n inputs and m outputs is described by m Boolean functions of the n inputs."],
    steps: ["Read the problem and decide the inputs and outputs.", "Write the truth table.", "Get the Boolean expression for each output.", "Simplify it using Boolean algebra or a K-map.", "Draw the logic diagram with gates."],
    formulas: [["Half adder", "Sum = A⊕B, Carry = A·B"], ["2-to-1 mux", "Y = S’·I0 + S·I1"]],
    example: { title: "Design: output is 1 when two or more of three inputs are 1 (majority)", text: "F = AB + BC + AC\nThis is a combinational circuit made with three AND gates and one OR gate." },
    exam: "A combinational circuit is a logic circuit whose output at any time depends only on the present values of its inputs. It contains no memory elements and no feedback. Examples are adders, multiplexers, decoders and comparators. Design steps: define inputs and outputs, write the truth table, derive and simplify the Boolean expressions, and draw the circuit.",
    mistakes: ["Adding a flip-flop and still calling it combinational. Any memory makes it sequential.", "Thinking the output can change on a clock. Combinational circuits do not need a clock.", "Forgetting to simplify before drawing the circuit."],
    uses: [["Calculator and processor arithmetic", "Adders and comparators inside the ALU are combinational."], ["Memory addressing", "Decoders pick one memory location from an address."], ["Data routing", "Multiplexers select one of many signals, for example in a phone’s audio path."]], related: ["Sequential logic", "Half adder and full adder", "Multiplexer", "Decoder"], diag: "combinational logic" },
  { id: "seq", keys: ["sequential logic", "sequential circuit", "sequential circuits", "sequential design", "sequential logic circuits", "synchronous sequential", "asynchronous sequential"], title: "Sequential logic", subject: "Digital electronics",
    short: "A sequential circuit is a digital circuit whose output depends on the present inputs and on the past, which it remembers using memory elements such as flip-flops.",
    points: ["It has two parts: a combinational circuit and memory (flip-flops) joined by feedback.", "In a synchronous sequential circuit all flip-flops change together on a clock edge. In an asynchronous one the state changes when the inputs change, with no clock.", "Examples: flip-flops, registers, counters, shift registers and finite state machines.", "Two models: Moore (outputs depend only on the state) and Mealy (outputs depend on the state and the inputs)."],
    steps: ["Draw the state diagram from the problem.", "Make the state table.", "Choose the flip-flop type and assign a binary code to each state.", "Write the flip-flop input equations.", "Write the output equations and draw the circuit."],
    formulas: [["Next state", "Q(next) = f(inputs, present state)"], ["Number of flip-flops", "n flip-flops store up to 2ⁿ states"]],
    example: { title: "A 2-bit counter", text: "Two flip-flops store the count 00, 01, 10, 11, then back to 00.\nThe next count depends on the present count, so it needs memory.\nThat makes it a sequential circuit." },
    exam: "A sequential circuit is a logic circuit whose output depends on the present inputs as well as the past sequence of inputs, which is stored in memory elements. It consists of a combinational circuit and flip-flops with feedback. It is classified as synchronous (clocked) or asynchronous, and as Moore or Mealy. Examples: registers, counters and state machines.",
    mistakes: ["Saying the output depends only on the present input. That is combinational.", "Forgetting the clock in a synchronous circuit.", "Mixing up Moore and Mealy. Mealy outputs also depend on the inputs."],
    uses: [["Digital clocks and timers", "Counters count seconds using flip-flops."], ["Traffic lights", "A state machine remembers the current light and moves to the next one."], ["Computer memory and registers", "Registers hold data between instructions."]], related: ["Combinational logic", "Flip-flops", "Counters", "Shift registers", "Finite state machine"], diag: "sequential logic" },
  { id: "ff", keys: ["flip flop", "flip flops", "flipflop", "latch", "latches", "sr flip flop", "jk flip flop", "d flip flop", "t flip flop", "race around", "master slave"], title: "Flip-flops (SR, D, JK, T)", subject: "Digital electronics",
    short: "A flip-flop is a one-bit memory element. It has two stable states (0 and 1), and changes state only on a clock edge.",
    points: ["A latch changes while its enable level is active. A flip-flop changes only on a clock edge (rising or falling).", "SR: S sets Q to 1, R resets Q to 0. S = R = 1 is not allowed.", "D: Q takes the value of D. It stores one bit.", "JK: like SR, but J = K = 1 toggles the output. This removes the invalid state.", "T: toggles when T = 1 and holds when T = 0. It is a JK with J and K tied together.", "Race-around: a level-triggered JK with J = K = 1 keeps toggling during the clock pulse. It is fixed by edge triggering or a master-slave design."],
    formulas: [["SR", "Q+ = S + R’Q   (SR = 0)"], ["D", "Q+ = D"], ["JK", "Q+ = JQ’ + K’Q"], ["T", "Q+ = T ⊕ Q"]],
    example: { title: "JK flip-flop, present Q = 0", text: "J=0 K=0 → Q+ = 0 (hold)\nJ=0 K=1 → Q+ = 0 (reset)\nJ=1 K=0 → Q+ = 1 (set)\nJ=1 K=1 → Q+ = 1 (toggle)" },
    exam: "A flip-flop is a bistable circuit that stores one bit and changes state only when triggered by a clock edge. The four types are SR, D, JK and T. Their characteristic equations are: SR, Q+ = S + R’Q; D, Q+ = D; JK, Q+ = JQ’ + K’Q; T, Q+ = T⊕Q. The JK flip-flop removes the invalid input of the SR flip-flop, and the master-slave arrangement removes its race-around problem.",
    mistakes: ["Saying SR with S = R = 1 is valid. It is forbidden (invalid).", "Mixing up a latch (level-triggered) and a flip-flop (edge-triggered).", "Forgetting that T = 1 toggles the output."],
    uses: [["Registers in processors", "Groups of D flip-flops hold the numbers the CPU is working on."], ["Frequency dividers", "A T flip-flop divides a clock by 2, used in watches and radios."], ["Switch debouncing", "An SR latch cleans up the noisy signal from a push button."]], related: ["Sequential logic", "Counters", "Shift registers"], diag: "flip-flop" },
  { id: "adder", keys: ["half adder", "full adder", "adder", "adders", "ripple carry", "ripple carry adder", "binary adder", "carry look ahead", "carry lookahead"], title: "Half adder and full adder", subject: "Digital electronics",
    short: "A half adder adds two bits and gives a sum and a carry. A full adder also takes a carry-in, so adders can be chained to add multi-bit numbers.",
    points: ["Half adder: Sum = A XOR B, Carry = A AND B. It needs one XOR and one AND gate.", "Full adder: Sum = A XOR B XOR Cin, Cout = AB + Cin(A XOR B). It can be built from two half adders and one OR gate.", "A ripple-carry adder chains n full adders. The carry has to ripple through every stage, so it gets slower as n grows.", "A carry-look-ahead adder works out the carries in advance, so it is faster but needs more gates."],
    formulas: [["Half adder", "Sum = A⊕B,  Carry = A·B"], ["Full adder sum", "Sum = A⊕B⊕Cin"], ["Full adder carry", "Cout = AB + Cin(A⊕B)"]],
    example: { title: "Full adder with A = 1, B = 1, Cin = 1", text: "Sum = 1⊕1⊕1 = 1\nCout = 1·1 + 1·(1⊕1) = 1\nSo 1 + 1 + 1 = 11 in binary (Cout = 1, Sum = 1)." },
    exam: "A half adder is a combinational circuit that adds two binary digits and produces a sum and a carry: Sum = A⊕B and Carry = A·B. A full adder adds three bits (A, B and carry-in): Sum = A⊕B⊕Cin and Cout = AB + Cin(A⊕B). A full adder can be made from two half adders and an OR gate. n full adders connected in a chain form an n-bit ripple-carry adder.",
    mistakes: ["Writing Carry = A + B for a half adder. It is A·B.", "Forgetting that a half adder has no carry input.", "Saying a ripple-carry adder is the fastest. It is the slowest of the common designs."],
    uses: [["Processor ALU", "Every addition, and also subtraction and counting, in a CPU uses adders."], ["Calculators", "Each digit is added with a full adder chain."], ["Address calculation", "The next memory address is found by adding to the present one."]], related: ["Combinational logic", "Multiplexer", "Logic gates"], diag: "adder" },
  { id: "mux", keys: ["multiplexer", "multiplexers", "mux", "demultiplexer", "demux"], title: "Multiplexer and demultiplexer", subject: "Digital electronics",
    short: "A multiplexer (MUX) selects one of many input lines and sends it to a single output. The select lines decide which input is chosen. A demultiplexer does the reverse.",
    points: ["A 2ⁿ-to-1 multiplexer has 2ⁿ data inputs, n select lines and 1 output. For example 4-to-1 needs 2 select lines.", "A demultiplexer (DEMUX) sends one input to one of many outputs, chosen by the select lines.", "A multiplexer can implement any Boolean function. A 2ⁿ-to-1 MUX can realise any function of n + 1 variables."],
    formulas: [["2-to-1", "Y = S’·I0 + S·I1"], ["4-to-1", "Y = S1’S0’I0 + S1’S0I1 + S1S0’I2 + S1S0I3"]],
    example: { title: "4-to-1 MUX with S1 S0 = 10", text: "S1 = 1 and S0 = 0 selects input I2.\nSo Y = I2." },
    exam: "A multiplexer is a combinational circuit with 2ⁿ data inputs, n select lines and one output. The select lines choose which data input is connected to the output. For a 4-to-1 multiplexer, Y = S1’S0’I0 + S1’S0I1 + S1S0’I2 + S1S0I3. It is used for data routing and to implement Boolean functions.",
    mistakes: ["Counting select lines wrongly. 8-to-1 needs 3 select lines, not 8.", "Mixing up MUX (many to one) and DEMUX (one to many).", "Forgetting the enable input when cascading multiplexers."],
    uses: [["Phone audio and camera paths", "A MUX picks the microphone, headset or speaker signal."], ["Telephone networks", "Many calls share one line using multiplexing."], ["CPU data paths", "A MUX picks which register feeds the ALU."]], related: ["Decoder", "Combinational logic", "Half adder and full adder"], diag: "multiplexer" },
  { id: "decoder", keys: ["decoder", "decoders", "encoder", "encoders", "priority encoder", "2 to 4 decoder", "3 to 8 decoder", "binary decoder"], title: "Decoder and encoder", subject: "Digital electronics",
    short: "A decoder converts an n-bit binary code into one active output out of 2ⁿ. An encoder does the opposite: it converts one active input into a binary code.",
    points: ["A 2-to-4 decoder has 2 inputs and 4 outputs. Exactly one output is 1 for each input combination (each output is a minterm).", "Most decoders have an enable input. When it is off, all outputs are 0.", "A priority encoder gives the code of the highest-priority active input when several are active.", "Decoders can build any Boolean function by OR-ing the minterm outputs."],
    formulas: [["2-to-4 outputs", "Y0 = A’B’,  Y1 = A’B,  Y2 = AB’,  Y3 = AB"], ["Size", "n inputs → 2ⁿ outputs"]],
    example: { title: "2-to-4 decoder, input AB = 10", text: "A = 1 and B = 0 gives Y2 = 1.\nY0, Y1 and Y3 stay 0." },
    exam: "A decoder is a combinational circuit that converts n input lines into a maximum of 2ⁿ output lines, where only one output is active for each input combination. For a 2-to-4 decoder, Y0 = A’B’, Y1 = A’B, Y2 = AB’ and Y3 = AB. An encoder performs the reverse operation by converting 2ⁿ inputs into an n-bit code.",
    mistakes: ["Saying more than one output is 1 in a normal decoder. Only one is active.", "Mixing up decoder and encoder.", "Forgetting the enable line."],
    uses: [["Memory chips", "The address decoder picks the one memory row to read or write."], ["Seven-segment displays", "A BCD-to-seven-segment decoder lights the right segments for a digit."], ["Keyboards", "An encoder turns the pressed key into a binary code."]], related: ["Multiplexer", "Combinational logic", "Logic gates"], diag: "" },
  { id: "counter", keys: ["counter", "counters", "ripple counter", "synchronous counter", "asynchronous counter", "mod counter", "up down counter", "johnson counter", "ring counter", "decade counter"], title: "Counters", subject: "Digital electronics",
    short: "A counter is a sequential circuit made of flip-flops that goes through a fixed sequence of states when it receives clock pulses.",
    points: ["Asynchronous (ripple) counter: the clock goes only to the first flip-flop and each flip-flop clocks the next. It is simple but slower, because delays add up.", "Synchronous counter: all flip-flops get the same clock, so it is faster but needs extra gates.", "A mod-N counter has N states and needs the smallest n with 2ⁿ ≥ N flip-flops.", "An n-bit binary counter divides the clock frequency by 2ⁿ.", "Ring counter has n states for n flip-flops. Johnson (twisted ring) counter has 2n states."],
    formulas: [["Flip-flops needed", "2ⁿ ≥ N"], ["Max count", "2ⁿ − 1"], ["Frequency division", "f_out = f_clock / 2ⁿ"]],
    example: { title: "Mod-10 (decade) counter", text: "N = 10, so 2⁴ = 16 ≥ 10 needs 4 flip-flops.\nIt counts 0000 to 1001, then resets to 0000." },
    exam: "A counter is a sequential circuit that counts the number of clock pulses applied to it. In an asynchronous counter the flip-flops are clocked one after another, while in a synchronous counter all flip-flops share the same clock. A mod-N counter needs n flip-flops where 2ⁿ ≥ N. An n-bit counter divides the input frequency by 2ⁿ.",
    mistakes: ["Calculating flip-flops wrongly. A mod-10 counter needs 4, not 10.", "Forgetting that ripple counters accumulate delay.", "Saying a 3-bit counter counts 1 to 8. It counts 0 to 7."],
    uses: [["Digital clocks and stopwatches", "Counters count seconds, minutes and hours."], ["Frequency meters", "They count pulses in one second to show the frequency."], ["Microcontroller timers", "Hardware counters create delays and PWM signals."]], related: ["Flip-flops", "Shift registers", "Sequential logic"], diag: "" },
  { id: "shift", keys: ["shift register", "shift registers", "siso", "sipo", "piso", "pipo", "universal shift register"], title: "Shift registers", subject: "Digital electronics",
    short: "A shift register is a group of flip-flops connected in a chain, so the stored bits move one place on every clock pulse.",
    points: ["n flip-flops store n bits.", "Four types: SISO (serial in, serial out), SIPO (serial in, parallel out), PISO (parallel in, serial out) and PIPO (parallel in, parallel out).", "SIPO and PISO are used to convert between serial and parallel data.", "Shifting an unsigned binary number left by one place multiplies it by 2. Shifting right divides it by 2."],
    formulas: [["Storage", "n flip-flops → n bits"], ["Delay (SISO)", "n clock pulses to move a bit through n stages"]],
    example: { title: "4-bit SIPO, input 1,0,1,1 sent serially", text: "After 4 clock pulses the four flip-flops hold the 4 bits at the same time, so the data can be read in parallel." },
    exam: "A shift register is a sequential circuit made of cascaded flip-flops in which the stored data shifts by one position at each clock pulse. Depending on how data enters and leaves, it is classified as SISO, SIPO, PISO or PIPO. It is used for serial-to-parallel conversion, delays and data storage.",
    mistakes: ["Forgetting that a SISO needs n clock pulses to move data out of n flip-flops.", "Mixing up SIPO and PISO.", "Using different clocks for each flip-flop. All share one clock."],
    uses: [["USB and serial ports", "Data arrives one bit at a time and is turned into bytes."], ["LED displays", "Shift registers drive many LEDs from a few microcontroller pins."], ["Calculators", "Shifts are used for fast multiplication and division by 2."]], related: ["Flip-flops", "Counters", "Sequential logic"], diag: "" },
  { id: "fsm", keys: ["finite state machine", "state machine", "fsm", "moore machine", "mealy machine", "moore", "mealy", "state diagram", "state table"], title: "Finite state machines (Moore and Mealy)", subject: "Digital electronics",
    short: "A finite state machine (FSM) is a sequential circuit with a limited number of states. At each clock edge it moves to a next state decided by the present state and the inputs.",
    points: ["Moore machine: the output depends only on the present state.", "Mealy machine: the output depends on the present state and the present inputs.", "A Mealy machine usually needs fewer states, and its outputs can react one clock earlier. A Moore machine’s outputs are cleaner and steadier.", "An FSM is drawn as a state diagram (circles and arrows) or a state table."],
    steps: ["Understand the problem and list the states.", "Draw the state diagram with the input conditions on the arrows.", "Make the state table (present state, input, next state, output).", "Assign binary codes to the states.", "Choose flip-flops and write the input and output equations.", "Draw the logic circuit."],
    formulas: [["Moore output", "Z = f(state)"], ["Mealy output", "Z = f(state, input)"], ["Flip-flops needed", "2ⁿ ≥ number of states"]],
    example: { title: "Detect the input sequence 11", text: "States: S0 (no 1 seen), S1 (one 1 seen), S2 (11 detected).\nInput 1 moves S0→S1→S2. Input 0 returns to S0.\nIn a Moore machine the output is 1 only in S2." },
    exam: "A finite state machine is a sequential circuit with a finite number of states. In a Moore machine the output depends only on the present state, whereas in a Mealy machine the output depends on both the present state and the present input. Design steps: state diagram, state table, state assignment, flip-flop input equations, output equations and logic diagram.",
    mistakes: ["Mixing up Moore and Mealy.", "Forgetting a transition for every input from every state.", "Using too few flip-flops for the number of states."],
    uses: [["Traffic lights", "Each light pattern is a state, and a timer input moves to the next."], ["Vending machines", "The state is the money inserted so far."], ["Network and game logic", "Protocols and game characters move between defined states."]], related: ["Sequential logic", "Flip-flops", "Counters"], diag: "finite-state machine" },
  { id: "opamp", keys: ["operational amplifier", "op amp", "opamp", "ideal op amp", "virtual ground", "virtual short"], title: "Operational amplifier (op-amp)", subject: "Analog electronics",
    short: "An op-amp is a high-gain voltage amplifier with two inputs (inverting and non-inverting) and one output. It amplifies the difference between its inputs.",
    points: ["An ideal op-amp has infinite open-loop gain, infinite input resistance, zero output resistance and infinite bandwidth.", "With negative feedback, the two inputs are at almost the same voltage (virtual short). If the non-inverting input is grounded, the inverting input is at virtual ground.", "Inverting amplifier: the output is inverted, gain = −Rf/Rin. Non-inverting amplifier: gain = 1 + Rf/Rin, never less than 1.", "Op-amps are used as amplifiers, adders, integrators, differentiators, comparators and filters."],
    formulas: [["Inverting gain", "Av = −Rf / Rin"], ["Non-inverting gain", "Av = 1 + Rf / Rin"], ["Voltage follower", "Av = 1"], ["Integrator", "Vout = −(1/RC) ∫ Vin dt"]],
    example: { title: "Inverting amplifier, Rin = 10 kΩ, Rf = 100 kΩ, Vin = 0.5 V", text: "Av = −100k / 10k = −10\nVout = −10 × 0.5 = −5 V" },
    exam: "An operational amplifier is a direct-coupled high-gain amplifier with a differential input and a single-ended output. An ideal op-amp has infinite gain, infinite input impedance and zero output impedance. With negative feedback, the inverting amplifier has gain −Rf/Rin and the non-inverting amplifier has gain 1 + Rf/Rin. The concept of virtual ground is used to analyse these circuits.",
    mistakes: ["Forgetting the minus sign of the inverting amplifier.", "Saying the non-inverting gain is Rf/Rin. It is 1 + Rf/Rin.", "Using the virtual-ground idea without negative feedback."],
    uses: [["Audio amplifiers and microphones", "Op-amps boost tiny microphone signals."], ["Sensors", "They amplify the small voltage from temperature or pressure sensors."], ["Filters and ADCs", "Used in phones and measurement instruments to clean and convert signals."]], related: ["Operational amplifier circuits", "BJT", "Rectifier"], diag: "operational amplifier" },
];
PACKS.push(
  { id: "numsys", keys: ["number system", "number systems", "binary number", "binary to decimal", "decimal to binary", "binary to hexadecimal", "hexadecimal", "octal", "base conversion", "number conversion", "radix"], title: "Number systems and conversions", subject: "Digital electronics",
    short: "A number system writes numbers with a fixed set of digits. Computers use binary (base 2). Octal (base 8) and hexadecimal (base 16) are short ways to write binary.",
    points: ["Decimal uses digits 0–9 (base 10). Binary uses 0 and 1 (base 2). Octal uses 0–7. Hexadecimal uses 0–9 and A–F, where A = 10 … F = 15.", "Binary to decimal: add the place values (powers of 2) where the bit is 1.", "Decimal to binary: divide by 2 again and again and read the remainders from bottom to top.", "Binary to octal: group the bits in 3s from the right. Binary to hexadecimal: group the bits in 4s from the right.", "Fractions: multiply the fraction by 2 again and again and read the whole parts from top to bottom.", "In a binary number the right-most bit is the least significant bit (LSB) and the left-most bit is the most significant bit (MSB). A group of 4 bits is a nibble and a group of 8 bits is a byte.", "n bits can represent the positive integers 0 to 2ⁿ − 1. In logic circuits, 0 is usually 0 V (ground) and 1 is the supply voltage of the circuit."],
    steps: ["Decimal to binary: divide the number by 2.", "Write down the remainder (0 or 1).", "Divide the quotient by 2 again until it becomes 0.", "Read the remainders from the last one to the first one."],
    formulas: [["Value of a number", "dₙ × bⁿ + … + d₁ × b¹ + d₀ × b⁰"], ["Hex digits", "A=10, B=11, C=12, D=13, E=14, F=15"], ["Bits needed", "n bits give 2ⁿ values (0 to 2ⁿ − 1)"]],
    example: { title: "Convert 25 to binary, and 1011 to decimal", text: "25 ÷ 2 = 12 r 1\n12 ÷ 2 = 6  r 0\n6 ÷ 2 = 3   r 0\n3 ÷ 2 = 1   r 1\n1 ÷ 2 = 0   r 1\nRead upwards: 25 = 11001₂\n\n1011₂ = 8 + 0 + 2 + 1 = 11\n110101₂ = 65₈ = 35₁₆\n\n857 ÷ 2 repeatedly gives remainders 1,0,0,1,1,0,1,0,1,1 (LSB first)\nSo 857 = 1101011001₂  (512 + 256 + 64 + 16 + 8 + 1)\n10110111₂ = 183" },
    exam: "A number system with base r uses r digits. Decimal has base 10, binary base 2, octal base 8 and hexadecimal base 16. A binary number is converted to decimal by adding the weights of the positions that hold 1. A decimal integer is converted to binary by repeated division by 2, taking the remainders in reverse order. Binary is converted to octal by grouping 3 bits and to hexadecimal by grouping 4 bits.",
    mistakes: ["Reading the remainders from top to bottom. Read them from bottom to top.", "Grouping bits from the left. Always group from the binary point.", "Forgetting that hex A–F stand for 10–15."],
    uses: [["Computer memory addresses", "Addresses are written in hexadecimal because it is shorter than binary."], ["Colour codes on websites", "#FF8800 is three hexadecimal bytes for red, green and blue."], ["Network addresses", "IP and MAC addresses are binary numbers shown in decimal or hex."]], related: ["Binary arithmetic and complements", "Binary codes", "Boolean algebra"], diagrams: ["place", "dec2bin"] },
  { id: "complement", keys: ["2s complement", "1s complement", "2's complement", "twos complement", "two's complement", "1's complement", "ones complement", "binary subtraction", "binary arithmetic", "signed binary", "sign magnitude", "overflow", "complements"], title: "Binary arithmetic and complements", subject: "Digital electronics",
    short: "Computers subtract by adding the 2’s complement of the number. In 2’s complement the leftmost bit is the sign (0 = positive, 1 = negative).",
    points: ["1’s complement: flip every bit. 2’s complement: 1’s complement + 1.", "Range of n-bit 2’s complement numbers: −2ⁿ⁻¹ to +2ⁿ⁻¹ − 1. For 4 bits: −8 to +7.", "A − B = A + (2’s complement of B). If a carry comes out of the leftmost bit, discard it and the answer is positive. If there is no carry, the answer is negative and is stored in 2’s complement form.", "Overflow happens when two numbers of the same sign are added and the result has the opposite sign."],
    steps: ["Write B in n bits.", "Flip all bits of B.", "Add 1 to get the 2’s complement.", "Add it to A.", "Look at the carry out to decide the sign."],
    formulas: [["2’s complement", "−N = 2ⁿ − N"], ["1’s complement", "bitwise NOT of the number"], ["Range", "−2ⁿ⁻¹ … 2ⁿ⁻¹ − 1"]],
    example: { title: "4-bit: 7 − 3", text: "3 = 0011\n1’s complement = 1100\n2’s complement = 1101\n7 + (−3) = 0111 + 1101 = 1 0100\nDiscard the carry: 0100 = 4" },
    exam: "The 2’s complement of a binary number is obtained by inverting all its bits and adding 1. Subtraction A − B is done by adding the 2’s complement of B to A. If there is a carry out, it is discarded and the result is positive; if there is no carry, the result is negative and is in 2’s complement form. An n-bit 2’s complement number represents values from −2ⁿ⁻¹ to 2ⁿ⁻¹ − 1.",
    mistakes: ["Forgetting to add 1 after flipping the bits.", "Keeping the final carry in 2’s complement subtraction.", "Mixing up the range: 4 bits give −8 to +7, not −7 to +8."],
    uses: [["Every processor", "The ALU does subtraction by adding the 2’s complement."], ["Temperature and sensor readings", "Negative values are stored in 2’s complement."], ["Programming", "Integer overflow bugs come from this same limit."]], related: ["Number systems and conversions", "Half and full adder", "Half and full subtractor"], diagrams: [] },
  { id: "codes", keys: ["binary code", "binary codes", "bcd", "gray code", "excess 3", "excess-3", "ascii", "8421", "alphanumeric code", "weighted code"], title: "Binary codes (BCD, Gray, Excess-3, ASCII)", subject: "Digital electronics",
    short: "A code uses groups of bits to represent numbers, letters or symbols. Different codes are used for different jobs.",
    points: ["BCD (8421): each decimal digit is written as its own 4-bit binary number. 25 = 0010 0101. The patterns 1010 to 1111 are not used.", "Gray code: two neighbouring numbers differ in only one bit. It stops errors in position sensors and is used in K-maps.", "Excess-3: BCD + 3. It is self-complementing, so the 9’s complement is found by flipping the bits.", "ASCII (American Standard Code for Information Interchange): 7-bit code for letters, digits and symbols. ‘0’ = 48 = 0110000, ‘A’ = 65 = 1000001 and ‘a’ = 97 = 1100001. Digits all start with 011 in the top three bits, and letters A to Z are in rising order, so sorting words is just comparing codes. A byte holds 7 ASCII bits plus one extra bit, often used as a parity bit.", "Binary to Gray: the first bit is the same. Each next Gray bit = XOR of that binary bit and the one before it. Gray to binary: the first bit is the same, then each binary bit = XOR of the previous binary bit and the Gray bit."],
    formulas: [["Binary to Gray", "Gₙ = Bₙ,  Gᵢ = Bᵢ ⊕ Bᵢ₊₁"], ["Gray to binary", "Bₙ = Gₙ,  Bᵢ = Bᵢ₊₁ ⊕ Gᵢ"], ["Excess-3", "Excess-3 = BCD + 0011"]],
    example: { title: "Convert binary 1011 to Gray", text: "G3 = B3 = 1\nG2 = B3 ⊕ B2 = 1 ⊕ 0 = 1\nG1 = B2 ⊕ B1 = 0 ⊕ 1 = 1\nG0 = B1 ⊕ B0 = 1 ⊕ 1 = 0\nGray = 1110\n\nBCD of 47 = 0100 0111\nExcess-3 of 5 = 0101 + 0011 = 1000" },
    exam: "A code is a set of bit patterns that represent numbers or characters. BCD represents each decimal digit by its 4-bit binary equivalent. The Gray code is a non-weighted code in which successive values differ in only one bit position. Excess-3 is obtained by adding 3 to the BCD digit and is self-complementing. ASCII is a 7-bit alphanumeric code.",
    mistakes: ["Using BCD codes 1010 to 1111. They are invalid.", "Calculating Gray code with addition instead of XOR.", "Calling Gray code a weighted code. It is not weighted."],
    uses: [["Digital clocks and calculators", "BCD makes it easy to show each decimal digit on a display."], ["Rotary encoders in machines", "Gray code avoids wrong readings between two positions."], ["Keyboards and text", "ASCII and Unicode turn key presses into numbers."]], related: ["Number systems and conversions", "Karnaugh map", "Parity and error detection"], diagrams: [] },
  { id: "sop", keys: ["sop", "pos", "sum of products", "product of sums", "minterm", "minterms", "maxterm", "maxterms", "canonical form", "standard form", "canonical sop"], title: "SOP, POS, minterms and maxterms", subject: "Digital electronics",
    short: "A minterm is an AND of all variables for one row of a truth table where the output is 1. A maxterm is an OR of all variables for a row where the output is 0. SOP is an OR of minterms; POS is an AND of maxterms.",
    points: ["Minterm mᵢ: each variable appears once, normal if its bit is 1 and complemented if its bit is 0. For A B C = 101, m5 = AB’C.", "Maxterm Mᵢ: each variable appears once, normal if its bit is 0 and complemented if its bit is 1. For ABC = 101, M5 = A’ + B + C’.", "A function in canonical SOP = Σm(rows where F = 1). The same function in canonical POS = ΠM(rows where F = 0).", "mᵢ’ = Mᵢ, so Σm(1,3,5,7) = ΠM(0,2,4,6) for three variables."],
    steps: ["Write the truth table.", "For SOP: for each row where F = 1, write the minterm and OR them.", "For POS: for each row where F = 0, write the maxterm and AND them.", "Simplify with a K-map or Boolean algebra."],
    formulas: [["SOP", "F = Σm(…) = OR of minterms"], ["POS", "F = ΠM(…) = AND of maxterms"], ["Relation", "Σm(F=1) = ΠM(F=0)"], ["Number of terms", "n variables give 2ⁿ minterms"]],
    example: { title: "F(A,B,C) is 1 for rows 1, 3, 5, 7", text: "F = Σm(1,3,5,7)\nF = A’B’C + A’BC + AB’C + ABC\nSimplified: F = C\nPOS form: F = ΠM(0,2,4,6)" },
    exam: "A minterm is a product term containing all the variables of the function in complemented or uncomplemented form, and it is 1 for exactly one input combination. A maxterm is a sum term with all the variables, and it is 0 for exactly one combination. The canonical sum of products is the OR of minterms where the function is 1, and the canonical product of sums is the AND of maxterms where the function is 0.",
    mistakes: ["Mixing up the rules: minterm uses 1 → normal, maxterm uses 0 → normal.", "Using the rows with F = 1 for POS. POS uses the rows where F = 0.", "Leaving out a variable in a canonical term."],
    uses: [["Circuit design from a truth table", "Engineers turn a table of required behaviour into gates."], ["Programmable chips (PLA, FPGA)", "Functions are stored as sums of products."], ["Exam questions", "Frequently asked together with K-map simplification."]], related: ["Karnaugh map", "Boolean algebra", "Quine–McCluskey method"], diagrams: ["kmap4"] },
  { id: "qm", keys: ["quine mccluskey", "quine-mccluskey", "tabular method", "qm method", "prime implicant", "prime implicants", "essential prime implicant"], title: "Quine–McCluskey (tabular) method", subject: "Digital electronics",
    short: "The Quine–McCluskey method simplifies a Boolean function by comparing minterms in a table. It works for any number of variables and can be programmed.",
    points: ["A prime implicant (PI) is a product term that cannot be combined with another to make a bigger group.", "An essential prime implicant covers at least one minterm that no other PI covers. It must be in the answer.", "It gives the same result as a K-map but is not limited to 4 or 5 variables.", "Decimal shortcut: two minterms in neighbouring groups combine if the larger number is exactly a power of 2 more than the smaller. Write that power in brackets, for example 0,8 (8). When combining pairs, the same powers in brackets must match.", "Don’t-cares are included when finding the prime implicants (they help make bigger terms) but are NOT listed in the columns of the prime-implicant chart, because they do not have to be covered.", "For product of sums, run the method on the 0s (the complement), then complement the answer.", "Starting from a function that is not in minterm form means converting it first, which is extra work. The tabular method is best for many variables or for a computer program; for up to 5 or 6 variables a map is quicker."],
    steps: ["List all minterms in binary and group them by the number of 1s.", "Compare minterms in neighbouring groups. If they differ in one bit, combine them and put a dash (−) in that bit. Tick the ones used.", "Repeat on the new list until nothing can be combined. The terms left unticked are the prime implicants.", "Make a PI chart: PIs in rows, minterms in columns.", "Pick the essential PIs, then add the fewest other PIs to cover the remaining minterms.", "Write each chosen PI as a product term and OR them."],
    formulas: [["Combine", "differ in 1 bit → replace that bit with −"], ["Dash", "− means the variable is eliminated"]],
    example: { title: "F(A,B,C) = Σm(0,1,3,7); then F(w,x,y,z) = Σ(0,1,2,8,10,11,14,15)", text: "Group by 1s: 000 | 001 | 011 | 111\nCombine: 00− (0,1), 0−1 (1,3), −11 (3,7)\nPIs: A’B’, A’C, BC\nm0 only in A’B’, m7 only in BC → both essential\nThese two already cover 0,1,3,7.\nF = A’B’ + BC\n\nFour variables: pairs 0,1(1)  0,2(2)  0,8(8)  2,10(8)  8,10(2)  10,11(1)  10,14(4)  11,15(4)  14,15(1)\nQuads: 0,2,8,10 (2,8) = x’z’  and  10,11,14,15 (1,4) = wy\nLeft over: 0,1(1) = w’x’y’\nF = w’x’y’ + x’z’ + wy" },
    exam: "The Quine–McCluskey method is a tabular technique for minimising Boolean functions. Minterms are grouped by the number of 1s and adjacent groups are compared; terms that differ in one bit are combined and the changed bit is replaced by a dash. The terms that cannot be combined further are the prime implicants. A prime implicant chart is then used to select the essential prime implicants and a minimum cover.",
    mistakes: ["Comparing terms that differ in two or more bits.", "Combining terms with dashes in different places.", "Forgetting to include the essential prime implicants."],
    uses: [["Computer-aided chip design", "Logic tools use this idea to shrink circuits automatically."], ["Large functions", "It works where a K-map would have too many variables."]], related: ["Karnaugh map", "SOP, POS, minterms and maxterms", "Boolean algebra"], diagrams: ["qmgroup"] },
  { id: "subtractor", keys: ["half subtractor", "full subtractor", "subtractor", "binary subtractor", "borrow"], title: "Half and full subtractor", subject: "Digital electronics",
    short: "A half subtractor subtracts two bits (A − B) and gives a difference and a borrow. A full subtractor also takes a borrow-in from the previous stage.",
    points: ["Half subtractor: Difference = A ⊕ B, Borrow = A’ · B.", "Full subtractor: Difference = A ⊕ B ⊕ Bin, Borrow-out = A’B + (A ⊕ B)’ · Bin.", "A full subtractor can be built from two half subtractors and an OR gate.", "Difference is the same as in an adder. Only the carry changes into a borrow."],
    formulas: [["Half subtractor", "D = A⊕B,  Bo = A’B"], ["Full subtractor D", "D = A⊕B⊕Bin"], ["Full subtractor Bo", "Bo = A’B + (A⊕B)’Bin"]],
    example: { title: "0 − 1 with a half subtractor", text: "A = 0, B = 1\nDifference = 0 ⊕ 1 = 1\nBorrow = 0’ · 1 = 1\nSo 0 − 1 = 1 with a borrow of 1." },
    exam: "A half subtractor is a combinational circuit that subtracts two bits and produces a difference and a borrow: D = A⊕B and Bo = A’B. A full subtractor subtracts three bits (A, B and the borrow-in): D = A⊕B⊕Bin and Bo = A’B + (A⊕B)’Bin. It can be made from two half subtractors and an OR gate.",
    mistakes: ["Writing Borrow = AB’. It is A’B.", "Confusing carry (adder) with borrow (subtractor).", "Forgetting the borrow input of a full subtractor."],
    uses: [["Processor ALU", "Used with adders to subtract numbers."], ["Counters", "Down counters use subtraction logic."]], related: ["Half and full adder", "Binary arithmetic and complements", "Combinational logic"], diagrams: ["halfsub"] },
  { id: "comparator", keys: ["comparator", "magnitude comparator", "digital comparator", "4 bit comparator", "7485"], title: "Magnitude comparator", subject: "Digital electronics",
    short: "A magnitude comparator compares two binary numbers A and B and tells whether A > B, A = B or A < B.",
    points: ["1-bit comparator: (A>B) = A·B’, (A=B) = (A⊕B)’, (A<B) = A’·B.", "For n-bit numbers, compare from the most significant bit. The first bit position where the bits differ decides the result.", "Two numbers are equal only if every bit pair is equal: (A=B) = product of the XNOR of each bit pair.", "The 7485 IC compares 4-bit numbers and can be cascaded for longer numbers."],
    formulas: [["A > B", "A·B’"], ["A = B", "(A⊕B)’ = A·B + A’·B’"], ["A < B", "A’·B"]],
    example: { title: "Compare A = 1010 and B = 1001", text: "MSB: 1 and 1 equal\nNext bit: 0 and 0 equal\nNext bit: 1 and 0 differ, and A has 1\nSo A > B" },
    exam: "A magnitude comparator is a combinational circuit that compares two binary numbers and produces three outputs: A>B, A=B and A<B. For single bits, A>B = AB’, A=B = (A⊕B)’ and A<B = A’B. For multi-bit numbers the comparison starts from the most significant bit.",
    mistakes: ["Starting the comparison from the least significant bit.", "Forgetting that A=B uses XNOR, not XOR."], uses: [["Digital thermostats", "Compare the measured temperature with the set value."], ["Sorting hardware and search", "Comparators decide the order of values."], ["Alarm and limit checks", "Raise an alert when a reading is above a limit."]],
    related: ["Half and full subtractor", "Logic gates", "Combinational logic"], diagrams: ["comp1"] },
  { id: "parity", keys: ["parity", "parity bit", "parity generator", "parity checker", "hamming code", "error detection", "error correction", "hamming"], title: "Parity and Hamming code (error detection)", subject: "Digital electronics",
    short: "A parity bit is an extra bit added to data so that the total number of 1s is even (even parity) or odd (odd parity). It can detect a single-bit error. A Hamming code can also correct it.",
    points: ["Even parity: add a bit so the total number of 1s is even. The parity bit is the XOR of the data bits.", "Parity detects any single-bit error but cannot say which bit is wrong, and it misses two-bit errors.", "Hamming(7,4): 4 data bits and 3 parity bits at positions 1, 2 and 4. The 3 parity checks together point to the exact position of a single wrong bit.", "Number of parity bits r needed for m data bits: 2ʳ ≥ m + r + 1."],
    steps: ["Place data bits at positions 3, 5, 6 and 7.", "p1 checks positions 1,3,5,7. p2 checks 2,3,6,7. p4 checks 4,5,6,7.", "Set each parity bit so that its group has an even number of 1s.", "At the receiver, recompute the 3 checks. The binary number formed (p4 p2 p1) is the position of the wrong bit; 000 means no error."],
    formulas: [["Even parity bit", "P = D₁ ⊕ D₂ ⊕ … ⊕ Dₙ"], ["Hamming bits", "2ʳ ≥ m + r + 1"], ["Hamming(7,4)", "p1 = d1⊕d2⊕d4,  p2 = d1⊕d3⊕d4,  p4 = d2⊕d3⊕d4"]],
    example: { title: "Hamming(7,4) for data 1011", text: "d1=1, d2=0, d3=1, d4=1\np1 = 1⊕0⊕1 = 0\np2 = 1⊕1⊕1 = 1\np4 = 0⊕1⊕1 = 0\nCodeword (positions 1..7): p1 p2 d1 p4 d2 d3 d4 = 0 1 1 0 0 1 1\n= 0110011" },
    exam: "A parity bit is an additional bit added to a binary word to make the number of 1s even (even parity) or odd (odd parity). It is used for single-bit error detection. The Hamming code adds several parity bits at positions that are powers of two, so that a single-bit error can be detected and corrected. For m data bits, the number of parity bits r satisfies 2ʳ ≥ m + r + 1.",
    mistakes: ["Thinking parity can correct errors. It can only detect.", "Putting Hamming parity bits at the wrong positions. They go at 1, 2, 4, 8 ….", "Forgetting that parity misses an even number of wrong bits."],
    uses: [["Computer memory (ECC RAM)", "Hamming-style codes fix single-bit memory errors."], ["Serial communication", "A parity bit is sent with every character."], ["QR codes and storage", "Stronger error-correcting codes recover damaged data."]], related: ["Binary codes", "Logic gates", "Combinational logic"], diagrams: ["parity"] },
  { id: "rom", keys: ["rom", "pla", "pal", "programmable logic", "programmable logic array", "programmable array logic", "read only memory", "fpga", "cpld"], title: "ROM, PLA and PAL (programmable logic)", subject: "Digital electronics",
    short: "ROM, PLA and PAL are chips whose connections can be programmed to make any combinational logic function.",
    points: ["ROM: a fixed AND array (a decoder that makes all minterms) and a programmable OR array. An n-input, m-output ROM stores 2ⁿ words of m bits and can implement any m functions of n variables.", "PLA: both the AND array and the OR array are programmable. It uses only the product terms that are needed, so it is smaller than a ROM.", "PAL: the AND array is programmable and the OR array is fixed. It is cheaper and simpler to use than a PLA.", "FPGA and CPLD are larger programmable chips made of many logic blocks and routing."],
    formulas: [["ROM size", "2ⁿ words × m bits"], ["Address lines", "n address lines → 2ⁿ locations"]],
    example: { title: "Size of a ROM that implements a 3-input, 4-output truth table", text: "n = 3 inputs → 2³ = 8 words\nm = 4 outputs → each word has 4 bits\nSize = 8 × 4 bits" },
    exam: "A read-only memory is a combinational device that consists of a decoder and an OR array and can implement any Boolean function by storing the truth table. In a PLA both the AND and OR planes are programmable, while in a PAL only the AND plane is programmable and the OR plane is fixed. These devices are used to realise combinational logic with a single chip.",
    mistakes: ["Mixing up PLA (both arrays programmable) and PAL (only AND array).", "Saying a ROM can be written as easily as a RAM."],
    uses: [["Phone and gadget firmware", "Start-up code is kept in ROM or flash."], ["Prototyping hardware", "FPGAs let engineers test a chip design before making it."], ["Lookup tables", "ROMs hold sine tables, fonts and code converters."]], related: ["Memory (RAM and ROM types)", "Decoder and encoder", "SOP, POS, minterms and maxterms"], diagrams: ["dec24"] },
  { id: "memory", keys: ["memory", "ram", "sram", "dram", "rom types", "eprom", "eeprom", "flash memory", "memory types", "volatile memory", "memory organisation", "memory organization"], title: "Memory (RAM and ROM types)", subject: "Digital electronics",
    short: "Digital memory stores bits. RAM can be read and written and loses its data when the power is off (volatile). ROM keeps its data without power (non-volatile).",
    points: ["SRAM stores a bit in a flip-flop: fast, no refresh, but bigger and costlier. Used in CPU caches.", "DRAM stores a bit as charge in a capacitor: small and cheap but must be refreshed. Used as main memory.", "ROM types: mask ROM (fixed at the factory), PROM (programmed once), EPROM (erased with UV light), EEPROM (erased electrically) and flash (erased in blocks).", "Capacity = 2^(address lines) × data bits. 10 address lines and 8 data bits → 1024 × 8 = 1 KB."],
    formulas: [["Capacity", "2ᵃ locations × w bits"], ["Address lines", "a = log₂(number of locations)"]],
    example: { title: "A memory chip has 12 address lines and 8 data lines", text: "Locations = 2¹² = 4096\nCapacity = 4096 × 8 bits = 4 KB" },
    exam: "Memory is a device that stores binary information. RAM is volatile read/write memory and may be static (SRAM, flip-flop based) or dynamic (DRAM, capacitor based, needs refreshing). ROM is non-volatile memory and includes PROM, EPROM, EEPROM and flash. A memory with k address lines and n data lines can store 2ᵏ words of n bits.",
    mistakes: ["Saying DRAM does not need refreshing.", "Mixing up capacity in bits and in bytes (8 bits = 1 byte).", "Counting address lines wrongly. 1K locations needs 10 address lines."],
    uses: [["Phones and laptops", "DRAM is the working memory and flash is the storage."], ["CPU caches", "SRAM keeps the most-used data close to the processor."], ["Boot code", "ROM or flash holds the first program a device runs."]], related: ["ROM, PLA and PAL", "Flip-flops", "Decoder and encoder"], diagrams: ["dec24"] },
  { id: "families", keys: ["logic family", "logic families", "ttl", "cmos", "ecl", "fan out", "fan in", "noise margin", "propagation delay", "power dissipation", "74 series", "7400", "7404", "7400 ic", "ssi", "msi", "lsi", "ic gates"], title: "Logic families (TTL, CMOS, ECL)", subject: "Digital electronics",
    short: "A logic family is a group of logic chips built with the same technology. TTL uses bipolar transistors, CMOS uses MOSFETs, and ECL is the fastest.",
    points: ["TTL (74 series): 5 V supply, fast, more power, fan-out about 10.", "CMOS: very low static power, high noise margin, wide supply voltage, high fan-out. It uses power mainly when switching: P ≈ C × V² × f.", "ECL: the fastest family because transistors never saturate, but it uses a lot of power and has a small noise margin.", "Key parameters: propagation delay, power dissipation, fan-out, fan-in and noise margin.", "TTL: the basic gate is NAND. ECL: the basic gate is NOR. CMOS: the basic circuit is the inverter, from which NAND and NOR are built. MOS and I²L give high density, so they are used for large chips (LSI).", "SSI chips hold a few gates in one package (a 14-pin package holds four 2-input gates: 3 pins each + 2 for power). MSI and LSI hold more. 7400 = quad 2-input NAND, 7404 = hex inverter, 10102 = ECL quad NOR, 4002 = CMOS dual 4-input NOR.", "TTL needs 5 V. CMOS (4000 series) works from 3 to 15 V. 5400 series is for the wide military temperature range and 7400 series for the narrower industrial range.", "Textbook typical values: standard TTL fan-out 10, 10 mW, 10 ns, noise margin 0.4 V; Schottky TTL 10, 22 mW, 3 ns; low-power Schottky 20, 2 mW, 10 ns; ECL 25, 25 mW, 2 ns, 0.2 V; CMOS 50, 0.1 mW, 25 ns, 3 V. These are old figures; modern CMOS is much faster.", "Total delay of a circuit = gate delay × number of logic levels. Fewer levels means a faster circuit, which can matter more than fewer gates.", "Fan-out: each extra input connected to an output adds load; a buffer can be used to drive heavy loads. Noise margin: the largest noise voltage that does not change the output; noise can be DC (drift) or AC (random pulses)."],
    formulas: [["Fan-out", "number of gate inputs one output can drive"], ["Noise margin", "NM = Vᴵᴸ − Vᴺᴸ (low),  NM = Vᴺᴴ − Vᴵᴴ (high)"], ["Speed-power product", "delay × power"], ["CMOS dynamic power", "P = C V² f"], ["Total delay", "gate delay × number of levels"]],
    example: { title: "Why do phones use CMOS?", text: "In CMOS, almost no current flows when the gate is not switching.\nSo the battery lasts longer and the chip stays cool." },
    exam: "A logic family is a group of compatible digital ICs made with the same technology. The main families are TTL, ECL and CMOS. Important characteristics are propagation delay, power dissipation, fan-out, fan-in and noise margin. CMOS has very low static power consumption and high noise immunity, TTL is fast with moderate power, and ECL is the fastest with the highest power consumption.",
    mistakes: ["Saying CMOS uses no power at all. It uses power while switching.", "Mixing up fan-in (inputs of a gate) and fan-out (loads an output can drive).", "Forgetting that unused TTL inputs float high."],
    uses: [["Mobile phones and laptops", "CMOS gives low power and long battery life."], ["High-speed communication equipment", "ECL was used where speed mattered most."], ["Hobby and lab circuits", "74-series TTL and CMOS chips are common in teaching labs."]], related: ["Logic gates", "Operational amplifier (op-amp)", "Memory (RAM and ROM types)"], diagrams: ["famtable", "gates"] },
  { id: "excite", keys: ["excitation table", "excitation tables", "characteristic table", "flip flop conversion", "convert flip flop", "state reduction", "state assignment"], title: "Excitation tables and flip-flop conversion", subject: "Digital electronics",
    short: "An excitation table tells which flip-flop inputs are needed to move from the present state Q to the next state Q+. It is used to design counters and state machines.",
    points: ["SR: 0→0: S=0, R=X. 0→1: S=1, R=0. 1→0: S=0, R=1. 1→1: S=X, R=0.", "JK: 0→0: J=0, K=X. 0→1: J=1, K=X. 1→0: J=X, K=1. 1→1: J=X, K=0.", "D: D = Q+.  T: T = Q ⊕ Q+ (T = 1 only when the state must change).", "X means don’t care: it can be 0 or 1, which helps to simplify the logic.", "To convert one flip-flop into another, write the excitation of the new one in terms of the old one."],
    steps: ["Draw the state diagram and state table.", "Choose the flip-flop type.", "For every present state and next state, read the needed inputs from the excitation table.", "Simplify each input with a K-map (use X as don’t care).", "Draw the circuit."],
    formulas: [["T flip-flop", "T = Q ⊕ Q+"], ["D flip-flop", "D = Q+"], ["JK from T", "T = J Q’ + K Q"]],
    example: { title: "JK flip-flop: Q = 0 and the next state must be 1", text: "From the excitation table 0→1 needs J = 1, K = X.\nThe flip-flop can be set with K = 0 or K = 1, so K is a don’t care." },
    exam: "The excitation table of a flip-flop lists the required inputs for each transition of the present state to the next state. For a JK flip-flop: 0→0 needs J=0, K=X; 0→1 needs J=1, K=X; 1→0 needs J=X, K=1; 1→1 needs J=X, K=0. Excitation tables are used in the design of counters and sequential circuits.",
    mistakes: ["Mixing up the characteristic table (inputs → next state) and the excitation table (transition → inputs).", "Not using the don’t cares to simplify.", "Reading the transition columns in the wrong order."],
    uses: [["Designing counters", "Exactly which J and K to use for each count."], ["Traffic-light controllers", "State tables become flip-flop input equations."]], related: ["Flip-flops (SR, D, JK, T)", "Counters", "Finite state machines (Moore and Mealy)"], diagrams: ["ffsym"] },
  { id: "hazard", keys: ["hazard", "hazards", "static hazard", "glitch", "static 1 hazard", "static 0 hazard", "dynamic hazard", "race condition"], title: "Hazards in logic circuits", subject: "Digital electronics",
    short: "A hazard is an unwanted short glitch at the output of a circuit, caused by gates having slightly different delays, even though the final logic value is correct.",
    points: ["Static-1 hazard: the output should stay 1 but drops to 0 for a moment. Static-0 hazard: the output should stay 0 but goes to 1 for a moment.", "Dynamic hazard: the output should change once (0→1) but changes several times.", "You can find a static-1 hazard on a K-map: two neighbouring 1s that are not covered by the same group.", "Fix: add the redundant (consensus) term that covers both neighbouring 1s."],
    formulas: [["Consensus", "AB + A’C + BC = AB + A’C"]],
    example: { title: "F = AB + A’C with B = C = 1 and A changing", text: "F should stay 1 (when A = 1, AB = 1; when A = 0, A’C = 1).\nBut when A changes, one term may turn off before the other turns on, so F glitches to 0.\nFix: add the term BC. F = AB + A’C + BC." },
    exam: "A hazard is a momentary incorrect output of a combinational circuit caused by unequal propagation delays in different paths. A static-1 hazard occurs when the output should remain at 1 but momentarily goes to 0. Static hazards are removed by adding redundant product terms (consensus terms) that cover adjacent 1s in the Karnaugh map.",
    mistakes: ["Thinking a hazard changes the final value. It is only a short glitch.", "Removing the redundant term during simplification and bringing the hazard back."],
    uses: [["Clock and reset logic", "A glitch can reset a counter by mistake."], ["Asynchronous circuits", "Hazards cause wrong state changes."]], related: ["Karnaugh map", "Combinational logic", "Sequential logic"], diagrams: ["kmap4"] },
  { id: "timingf", keys: ["setup time", "hold time", "clock skew", "metastability", "maximum clock frequency", "clock to q", "timing analysis", "propagation delay of flip flop"], title: "Timing: setup time, hold time and clock frequency", subject: "Digital electronics",
    short: "For a flip-flop to work, its data input must be steady for a short time before the clock edge (setup time) and after it (hold time).",
    points: ["Setup time (t_su): D must be stable this long before the active clock edge.", "Hold time (t_h): D must stay stable this long after the clock edge.", "Clock-to-Q delay (t_cq): the time from the clock edge until Q changes.", "If setup or hold is violated, the flip-flop can become metastable: it stays between 0 and 1 for a while and can give a wrong value.", "The clock period must be at least t_cq + t_logic + t_su, so the maximum clock frequency f_max = 1 / (t_cq + t_logic + t_su)."],
    formulas: [["Minimum clock period (clock skew ignored)", "T ≥ t_cq + t_logic + t_su"], ["Maximum frequency", "f_max = 1 / T_min"], ["Hold condition", "t_cq + t_logic(min) ≥ t_h"]],
    example: { title: "t_cq = 2 ns, t_logic = 5 ns, t_su = 1 ns", text: "T_min = 2 + 5 + 1 = 8 ns\nf_max = 1 / 8 ns = 125 MHz" },
    exam: "The setup time of a flip-flop is the minimum time before the active clock edge during which the data input must be stable, and the hold time is the minimum time after the edge during which it must stay stable. The maximum clock frequency of a synchronous circuit is 1 / (t_cq + t_logic + t_su). A violation of setup or hold time can lead to metastability.",
    mistakes: ["Adding hold time to the clock period formula. Only setup time is added.", "Ignoring the flip-flop’s own clock-to-Q delay."],
    uses: [["Processor design", "The clock speed of a CPU is limited by this sum of delays."], ["FPGA design", "Tools report setup and hold violations that must be fixed."]], related: ["Flip-flops (SR, D, JK, T)", "Sequential logic", "Logic families"], diagrams: ["timing"] },
  { id: "hdl", keys: ["verilog", "hdl", "vhdl", "hardware description language", "testbench", "blocking and nonblocking", "always block", "behavioural modelling", "structural modelling"], title: "Hardware description languages (Verilog basics)", subject: "Digital electronics",
    short: "A hardware description language (HDL), such as Verilog or VHDL, describes a digital circuit as text, so it can be simulated and then built on a chip or FPGA.",
    points: ["A circuit is written as a module with inputs and outputs.", "Combinational logic: use assign or always @(*) with blocking assignments (=).", "Sequential logic: use always @(posedge clk) with non-blocking assignments (<=).", "A testbench is a module with no ports that applies inputs to the design under test and shows the outputs.", "Styles: structural (connect gates), dataflow (assign) and behavioural (always blocks).", "Gate primitives: and (y, x1, x2); or (y, x1, x2, x3); not (y, x); nand and nor work the same way. The output is always written first.", "Operators: ~ is NOT, & is AND, | is OR and ^ is XOR. So f = (~s & x1) | (s & x2) is a 2-to-1 multiplexer.", "Names must start with a letter and may use letters, digits, _ and $. Verilog is case sensitive. Comments start with //.", "A signal assigned inside an always block must be declared reg. always @(*) lets the compiler find the inputs itself.", "Hierarchy: write small modules and connect them in a top-level module. Internal connections are declared wire, for example: wire w1, w0; adder U1 (x, y, w1, w0);", "Write code so you can see the circuit it makes. If you cannot tell what circuit the code describes, the tools may not build what you want."],
    formulas: [["Combinational", "assign y = a & b;"], ["Sequential", "always @(posedge clk) q <= d;"]],
    example: { title: "Half adder and 2-to-1 multiplexer in Verilog", text: "module half_adder(input a, b, output sum, carry);\n  assign sum   = a ^ b;\n  assign carry = a & b;\nendmodule\n\n// 2-to-1 mux, gate level\nmodule mux2(x1, x2, s, f);\n  input x1, x2, s;\n  output f;\n  not (k, s);\n  and (g, k, x1);\n  and (h, s, x2);\n  or  (f, g, h);\nendmodule\n\n// same mux, one line\nassign f = (~s & x1) | (s & x2);" },
    exam: "A hardware description language is a language used to describe the structure and behaviour of digital circuits. In Verilog a design is written as a module with input and output ports. Combinational circuits are described using continuous assignments (assign) or always @(*) blocks, and sequential circuits using always @(posedge clk) blocks with non-blocking assignments. A testbench is used to simulate the design.",
    mistakes: ["Using blocking (=) assignments for flip-flops. Use non-blocking (<=).", "Forgetting a default value, which creates an unwanted latch.", "Mixing up simulation-only code with code that can be built into hardware.", "Writing the output last in a gate primitive. The output comes first: and (y, x1, x2).", "Using a signal in an always block without declaring it reg."],
    uses: [["Designing chips and FPGAs", "Engineers write HDL instead of drawing millions of gates."], ["Testing before manufacture", "Simulation finds bugs before spending money on a chip."]], related: ["Half and full adder", "Flip-flops (SR, D, JK, T)", "Finite state machines (Moore and Mealy)"], diagrams: [] },
);
const DMAP = { gates: ["gates", "gatetruth", "nand_univ"], kmap: ["kmap4"], ff: ["ffsym", "srlatch", "timing"], adder: ["halfadder", "fulladder"], mux: ["mux2"], decoder: ["dec24"], counter: ["ripple"], shift: ["sipo"] };
PACKS.forEach(p => { if (!p.diagrams) p.diagrams = DMAP[p.id] || []; });
PACKS.push(
  { id: "dvsa", keys: ["digital and analog", "analog and digital", "digital vs analog", "analog vs digital", "digital information", "analog information", "bits needed", "minimum number of bits", "how many bits", "d a converter", "range of binary number"], title: "Digital and analog information; how many bits", subject: "Digital electronics",
    short: "Digital information is stored as 0s and 1s. Analog information is a smoothly changing voltage. A D/A converter changes digital numbers into an analog voltage, and n bits can show 2ⁿ different values.",
    points: ["Each digit in a logic circuit has only two values, 0 and 1. Logic 0 is usually 0 V (ground) and logic 1 is the supply voltage of the circuit.", "A music file is a long list of binary numbers. Stored in memory it is digital information.", "A digital-to-analog (D/A) converter changes those numbers into a changing voltage. That voltage drives the speaker or headphones and is analog information.", "n bits can show 2ⁿ different patterns, so the largest unsigned number is 2ⁿ − 1.", "To find the bits needed for a number N, find the smallest n with 2ⁿ > N.", "Second way to convert decimal to binary: subtract the largest power of 2 that fits, mark a 1 at that place, and repeat with what is left."],
    steps: ["Take the number N.", "Find the smallest n such that 2ⁿ is bigger than N.", "That n is the number of bits needed.", "To write the binary form, subtract the biggest power of 2 that fits and put 1 in its place; put 0 in places that were skipped."],
    formulas: [["Values with n bits", "2ⁿ"], ["Largest unsigned number", "2ⁿ − 1"], ["Bits for number N", "smallest n with 2ⁿ > N"]],
    example: { title: "Bits needed and the power-of-2 method", text: "270: 2⁸ = 256 ≤ 270 < 512 = 2⁹  → 9 bits\n520 → 10 bits,  780 → 10 bits,  1029 → 11 bits\n\n23 = 16 + 4 + 2 + 1 = 2⁴ + 2² + 2¹ + 2⁰\nSo 23 = 10111₂\n\nPractice: 20 = 10100₂,  100 = 1100100₂,  129 = 10000001₂,  260 = 100000100₂" },
    exam: "Digital information is represented by two-valued signals, 0 and 1, whereas analog information is a continuously varying voltage. A digital-to-analog converter converts stored binary values into an analog voltage that drives a speaker. With n bits, 2ⁿ distinct values from 0 to 2ⁿ − 1 can be represented.",
    mistakes: ["Saying n bits go up to 2ⁿ. The largest number is 2ⁿ − 1.", "Mixing up digital (two levels) and analog (any level).", "Forgetting that 0 needs a pattern too, so 4 bits give 16 values, not 15."],
    uses: [["Music and video players", "Stored bits are changed to sound by a D/A converter."], ["Choosing memory width", "Engineers pick the number of bits so every value fits."], ["Sensors and microphones", "An A/D converter does the opposite and turns a voltage into bits."]], related: ["Number systems and conversions", "Binary codes", "Sampling and quantization"], diagrams: ["dacpath", "bitsrange"] },
  { id: "swlogic", keys: ["logic function", "logic functions", "switch logic", "series and parallel switches", "logic from switches", "truth table", "truth tables", "logic variable", "logic circuit basics", "inversion", "complement operation", "precedence of operations", "operator precedence"], title: "Logic functions, switches and truth tables", subject: "Digital electronics",
    short: "A logic function says what the output is for every combination of inputs. A switch with a lamp shows the idea: switches in series make AND, switches in parallel make OR, and a switch across the lamp makes NOT.",
    points: ["A switch controlled by input x is open when x = 0 and closed when x = 1. The lamp is on when L = 1.", "Two switches in series: the lamp is on only if both are closed. This is the AND function, L = x₁ · x₂.", "Two switches in parallel: the lamp is on if either one is closed. This is the OR function, L = x₁ + x₂. Here + means OR, not arithmetic addition.", "A switch in parallel with the lamp (with a resistor in the supply path) turns the lamp on when the switch is open. This is NOT, L = x’. Other ways to write NOT: x̄, !x, ~x.", "A truth table lists every combination of input values (a valuation). n input variables give 2ⁿ rows: 3 variables give 8 rows and 4 variables give 16 rows.", "AND of n variables is 1 only if all n are 1. OR of n variables is 1 if one or more is 1.", "Order of operations: NOT first, then AND, then OR. So x₁x₂ + x₁’x₂’ means (x₁·x₂) + ((x₁’)·(x₂’)). The · sign is often left out."],
    steps: ["List the input variables.", "Write all 2ⁿ valuations in counting order 000, 001, 010 …", "Work out the output for each row using AND, OR and NOT.", "Check the order: NOT, then AND, then OR."],
    formulas: [["AND", "L = x₁ · x₂"], ["OR", "L = x₁ + x₂"], ["NOT", "L = x’"], ["Series-parallel example", "L = (x₁ + x₂) · x₃"], ["Rows in a truth table", "2ⁿ for n inputs"]],
    example: { title: "Truth table for AND and OR", text: "x₁ x₂ | x₁·x₂ | x₁+x₂\n 0  0 |   0   |   0\n 0  1 |   0   |   1\n 1  0 |   0   |   1\n 1  1 |   1   |   1\n\nL = (x₁ + x₂)·x₃ is on only when x₃ = 1 and at least one of x₁, x₂ is 1." },
    exam: "A logic function describes the output of a logic circuit in terms of its input variables. AND is realised by switches in series, OR by switches in parallel and NOT (complement) by a switch connected across the load. The behaviour of a function is shown in a truth table which has 2ⁿ rows for n variables. In an expression, NOT has the highest precedence, then AND, then OR.",
    mistakes: ["Reading + as ordinary addition. In logic 1 + 1 = 1.", "Forgetting the precedence: AND is done before OR.", "Writing a truth table with fewer than 2ⁿ rows."],
    uses: [["Torch and lamp circuits", "A switch controlling a lamp is the simplest logic circuit."], ["Alarm panels", "Series and parallel contacts make AND and OR of door and window sensors."], ["Writing the spec of a chip", "A truth table is the first step of any design."]], related: ["Logic gates", "Boolean algebra", "Synthesis and analysis of logic circuits"], diagrams: ["switches"] },
  { id: "synth", keys: ["synthesis", "analysis of logic network", "logic network", "logic circuit synthesis", "functionally equivalent", "functional equivalence", "circuit cost", "cost of a circuit", "truth table to circuit", "three way light control", "xor from gates", "timing diagram", "propagation delay of a gate"], title: "Analysis and synthesis of logic circuits", subject: "Digital electronics",
    short: "Analysis finds the function of a given circuit. Synthesis builds a circuit for a given function. Many circuits can give the same function, so we choose the cheapest one.",
    points: ["Analysis: apply every input valuation to the circuit and note the output. This gives the truth table. It is easy.", "Synthesis: start from a truth table and design a circuit. It is harder. The simplest way: write one AND (product) term for each row where the output is 1, then OR all the terms.", "Two circuits are functionally equivalent if they give the same output for every input. Example: x₁’ + x₁x₂ and x₁’ + x₂ are equivalent, so the simpler one is used.", "Cost of a circuit = number of gates + total number of gate inputs. The cheaper circuit is smaller and usually faster.", "A timing diagram shows input and output waveforms against time. Ideal diagrams change instantly. In a real gate there is a small propagation delay between an input change and the output change.", "XOR: L = x ⊕ y = x’y + xy’. It is 1 when the inputs are different. It is used in adders: for adding two bits, sum bit s₀ = a ⊕ b and carry s₁ = a · b.", "Multiplexer: f = s’x₁ + s x₂. When s = 0 the output is x₁ and when s = 1 it is x₂."],
    steps: ["Write the truth table for the required behaviour.", "For every row with output 1, write a product term with all variables (x if 1, x’ if 0).", "OR the product terms. This is the canonical sum of products.", "Simplify with Boolean algebra or a K-map.", "Count the cost and draw the circuit."],
    formulas: [["Cost", "number of gates + number of gate inputs"], ["XOR", "x ⊕ y = x’y + xy’"], ["2-to-1 mux", "f = s’x₁ + s x₂"], ["Half adder", "sum = a ⊕ b,  carry = a · b"]],
    example: { title: "Light controlled by three switches", text: "The light must change when any one switch changes.\nIt is on when exactly one or all three switches are 1.\nf = Σm(1, 2, 4, 7) = x₁’x₂’x₃ + x₁’x₂x₃’ + x₁x₂’x₃’ + x₁x₂x₃\nThis cannot be simplified in sum-of-products form.\n(It is the 3-input XOR: x₁ ⊕ x₂ ⊕ x₃.)\n\nCost check for f = Σm(1,4,5,6):\nCanonical form: 4 AND gates (3 inputs each), 1 OR gate (4 inputs), 3 NOT gates = 8 gates + 19 inputs = 27\nSimplified f = x₂’x₃ + x₁x₃’: 2 NOT, 2 AND, 1 OR = 5 gates + 8 inputs = 13" },
    exam: "Analysis is the process of finding the function realised by a given logic network, whereas synthesis is the process of designing a network for a given function. A function in truth-table form can be synthesised as a sum of the minterms for which the output is 1. Different networks may realise the same function; the cost of a network is the number of gates plus the number of gate inputs, and the aim is to find the minimum-cost network. A timing diagram shows the waveforms of the inputs and outputs against time.",
    mistakes: ["Forgetting that a simpler expression can have the same truth table. Always try to simplify.", "Counting only the gates and forgetting the inputs when finding cost.", "Mixing up analysis (circuit → function) and synthesis (function → circuit)."],
    uses: [["Staircase lights", "A light controlled from two or three places uses an XOR-type function."], ["Data selection in computers", "A multiplexer picks one of several data sources."], ["Quality check on a design", "Engineers prove two designs are equivalent before replacing a circuit."]], related: ["Logic functions, switches and truth tables", "SOP, POS, minterms and maxterms", "Minimization: prime implicants and cost"], diagrams: ["halfadder", "mux2"] },
  { id: "venn", keys: ["venn diagram boolean", "venn diagram in boolean algebra", "venn diagrams for logic", "prove boolean identity", "perfect induction", "dual of boolean", "duality principle", "consensus theorem", "consensus"], title: "Venn diagrams and proving Boolean identities", subject: "Digital electronics",
    short: "A Venn diagram is a picture proof for Boolean identities. Shade the area where an expression is 1. If both sides of an identity give the same shaded area, the identity is true.",
    points: ["The big square is the universe (constant 1). An empty square is constant 0.", "A circle x is the area where x = 1. The area outside the circle is x’.", "x · y is the overlap of the circles (intersection). x + y is the area covered by both circles (union).", "Perfect induction: put every input combination in a truth table and check that both sides match. It always works but is slow for many variables.", "Duality: swap AND with OR and 0 with 1 in a true law and you get another true law. Example: x + x·y = x and x · (x + y) = x.", "Consensus: x·y + x’·z + y·z = x·y + x’·z. The term y·z is already covered by the other two, so it can be removed.", "Useful forms: x + x’y = x + y and x(x’ + y) = xy."],
    steps: ["Draw circles for the variables (two or three).", "Shade the area for the left side of the identity.", "Shade the area for the right side.", "If the two shaded areas are the same, the identity is proved."],
    formulas: [["De Morgan", "(x · y)’ = x’ + y’,  (x + y)’ = x’ · y’"], ["Distributive", "x(y + z) = xy + xz,  x + yz = (x + y)(x + z)"], ["Absorption", "x + xy = x,  x(x + y) = x"], ["Combining", "xy + xy’ = x,  (x + y)(x + y’) = x"], ["Consensus", "xy + x’z + yz = xy + x’z"]],
    example: { title: "Prove x + yz = (x + y)(x + z)", text: "Left side: circle x together with the overlap of y and z.\nRight side: (x + y) is both circles; (x + z) is the x circle with the z circle.\nTheir overlap = all of x plus the part where y and z overlap.\nThe two shaded areas are the same, so the identity is true.\n\nThis identity does NOT work in ordinary algebra with numbers, but it is true in Boolean algebra." },
    exam: "The Venn diagram is a graphical method of verifying Boolean identities. The universe represents 1, a variable is a circle and the area inside the circle represents the value 1. The AND of two variables is the intersection and the OR is the union of their areas. Two expressions are equal if they have the same shaded area. The principle of duality states that the dual of a true statement, obtained by interchanging AND with OR and 0 with 1, is also true.",
    mistakes: ["Shading the area outside the circle for x. That is x’.", "Using the second distributive law x + yz = (x + y)(x + z) as if it were ordinary algebra. It is special to Boolean algebra.", "Forgetting the dual of a law when only one form is remembered."],
    uses: [["Checking an exam answer", "Draw a quick Venn diagram to see if two expressions are equal."], ["Database and web search", "Combining search words with AND/OR is the same as intersection and union."], ["Simplifying logic", "Shaded areas show which terms are redundant."]], related: ["Boolean algebra", "Karnaugh map", "Logic functions, switches and truth tables"], diagrams: ["bvenn"] },
  { id: "minim", keys: ["minimization", "minimisation", "literal", "implicant", "implicants", "minimum cost", "minimum cost circuit", "don t care", "dont care", "don't care", "incompletely specified", "five variable k map", "5 variable k map", "multiple output circuit", "product of sums minimization", "k map pos"], title: "Minimization: prime implicants, don’t-cares and cost", subject: "Digital electronics",
    short: "To get the cheapest circuit, cover all the 1s of a function with as few and as large product terms as possible. The largest groups are the prime implicants; the ones that must be used are the essential prime implicants.",
    points: ["Literal: one appearance of a variable, complemented or not. x₁x₂’x₃ has 3 literals.", "Implicant: a product term that is 1 only where the function is 1. Minterms are the smallest implicants.", "Prime implicant: an implicant that cannot be made larger. You cannot remove any of its literals and still have an implicant. On a K-map it is the largest possible group of 1s.", "Cover: a set of implicants that together include all the 1s. A cover made of prime implicants gives the cheapest circuit.", "Essential prime implicant: it is the only one that covers some minterm. It must be in the answer.", "Method: (1) find all prime implicants, (2) pick the essential ones, (3) if some 1s are still uncovered, add the cheapest extra prime implicants.", "Don’t-care (d): an input combination that never happens. You may treat it as 1 or 0, whichever makes the groups bigger. Written f = Σm(…) + D(…).", "Product-of-sums: group the 0s of the K-map instead and write a sum term for each group. Or minimise the complement f’ as SOP and apply De Morgan.", "A 5-variable map is two 4-variable maps side by side (x₅ = 0 and x₅ = 1). Cells in the same place in both maps are neighbours.", "Multiple outputs: if two functions use the same product term, one AND gate can be shared, which lowers the total cost.", "A don’t-care can never be marked as 1 or as 0 on the map; it is marked X (or d). If you treat the same X as 1 for the SOP and as 0 for the POS, the two answers are not the same function (they differ only on the don’t-care inputs), and that is fine.", "The minimum-literal answer is not always unique: sometimes two terms cost the same and either may be chosen."],
    steps: ["Draw the K-map and mark the 1s (and d for don’t-cares).", "Circle every largest group of 1s: these are the prime implicants. Use d cells only to make groups bigger.", "Mark the essential ones (a 1 covered by only one group).", "Cover any left-over 1s with the cheapest groups.", "Write the term of each group and OR them."],
    formulas: [["Cost", "gates + gate inputs (complemented inputs are free)"], ["Group of 2ᵏ cells", "removes k variables"], ["Don’t-care notation", "f = Σm(…) + D(…)"], ["POS from 0s", "f = ΠM(rows where f = 0)"]],
    example: { title: "Prime implicants and don’t-cares", text: "f = Σm(0,1,2,3,7) on three variables:\nPrime implicants: x₁’ (cells 0,1,2,3) and x₂x₃ (cells 3,7).\nBoth are essential, so f = x₁’ + x₂x₃.\n\nWith don’t-cares: f = Σm(2,4,5,6,10) + D(12,13,14,15)\nTake all four d cells as 1:\nf = x₂x₃’ + x₃x₄’\n(Treating d as 0 gives a bigger, costlier circuit.)\n\nPOS from the 0s: f = ΠM(4,5,6) = (x₁’ + x₂)(x₁’ + x₃)\n\nSecond don’t-care example: F = Σ(1,3,7,11,15), d = Σ(0,2,5)\nSOP: F = w’z + yz.   POS (X’s as 0): F = z(w’ + y)" },
    exam: "A prime implicant is a product term that cannot be combined with another term to eliminate a literal. An essential prime implicant covers at least one minterm that no other prime implicant covers. A minimum-cost sum-of-products expression is obtained by choosing all essential prime implicants and the fewest extra prime implicants needed to cover the remaining minterms. Don’t-care conditions are input combinations that never occur and may be assigned 1 or 0 to simplify the function.",
    mistakes: ["Making a smaller group when a bigger group of 1s is possible.", "Treating every don’t-care as 1. Use only those that make a group bigger.", "Forgetting that the left and right edges (and top and bottom) of a K-map are neighbours."],
    uses: [["Seven-segment decoders", "Digits 10 to 15 never occur in BCD, so they are don’t-cares that shrink the circuit."], ["Interlocked controls", "Two switches that can never be on together create a don’t-care case."], ["Chip design tools", "Software does the same steps automatically for hundreds of variables."]], related: ["Karnaugh map", "Quine–McCluskey (tabular) method", "SOP, POS, minterms and maxterms"], diagrams: ["kmap3pi", "kmap4"] },
  { id: "nandnor", keys: ["nand only", "nor only", "only nand gates", "only nor gates", "nand gates only", "nor gates only", "implement using only nand gates", "using nand gates", "using nor gates", "nand implementation", "nor implementation", "nand nand", "nor nor", "implement with nand", "implement using nand", "nand and nor networks", "universal gate implementation", "and or to nand"], title: "Building circuits with only NAND or only NOR gates", subject: "Digital electronics",
    short: "Any AND–OR circuit can be redrawn with only NAND gates, and any OR–AND circuit with only NOR gates. NAND and NOR gates are simpler to build in hardware, so this saves cost.",
    points: ["De Morgan’s theorem as gates: a NAND is the same as an OR gate with inverted inputs. A NOR is the same as an AND gate with inverted inputs.", "Sum of products (AND–OR) becomes NAND–NAND with the same structure.", "Product of sums (OR–AND) becomes NOR–NOR with the same structure.", "Reason: put two inverters on each wire between the first and second level (a double inversion changes nothing). One inverter turns the AND gate into NAND, the other turns the OR gate into a NAND with inverted inputs.", "A NAND (or NOR) with its inputs tied together is a NOT gate.", "A single variable that goes straight to the second-level gate must be inverted twice, or inverted once through a tied NAND (so the sign is right).", "Example F = AB + CD + E: draw NAND gates for AB and CD, and feed E′ (or E through a one-input NAND) to the second-level NAND. Check: F = ((AB)′(CD)′E′)′ = AB + CD + E.", "Example F = (A + B)(C + D)E with NOR gates: NOR for (A + B) and (C + D), and feed E′ to the second-level NOR. Check: F = ((A + B)′ + (C + D)′ + E′)′ = (A + B)(C + D)E.", "NAND and NOR gates are easier to build with transistors than AND and OR gates, so they are far more common in ICs."],
    steps: ["Write the minimum SOP (for NAND) or POS (for NOR).", "Draw the AND–OR (or OR–AND) circuit.", "Replace every gate by NAND (or NOR).", "A lone input that skips the first level needs an extra inverter (a tied NAND/NOR) to keep its value correct."],
    formulas: [["NAND as OR", "(x₁ · x₂)’ = x₁’ + x₂’"], ["NOR as AND", "(x₁ + x₂)’ = x₁’ · x₂’"], ["NOT from NAND", "(x · x)’ = x’"]],
    example: { title: "f = Σm(2,3,4,6,7) with NAND only", text: "SOP: f = x₂ + x₁x₃’\nNAND form: f = ( (x₂’) · (x₁x₃’)’ )’ = x₂ + x₁x₃’\nGates: NAND(x₂,x₂) gives x₂’, NAND(x₃,x₃) gives x₃’, NAND(x₁,x₃’) gives the product term, and a final NAND joins them.\n\nSame function with NOR only: POS f = (x₁ + x₂)(x₂ + x₃’) → two NOR gates and a final NOR, with x₃ inverted by a NOR whose inputs are tied." },
    exam: "A sum-of-products circuit can be implemented as a NAND–NAND network and a product-of-sums circuit as a NOR–NOR network. By placing two inverters in each connection between the AND and OR levels and using De Morgan’s theorem, the AND gates become NAND gates and the OR gate becomes a NAND gate with inverted inputs, which is a NAND gate. NAND and NOR gates are preferred because they are simpler to implement electronically.",
    mistakes: ["Replacing the gates but forgetting the extra inverter for a lone variable.", "Using NAND for a POS circuit. POS needs NOR–NOR.", "Thinking the NAND form needs a different expression. The structure stays the same."],
    uses: [["Chip manufacturing", "Gates built from transistors are cheapest as NAND or NOR."], ["Exam circuits", "“Implement using only NAND gates” is a standard question."]], related: ["Logic gates", "Boolean algebra", "SOP, POS, minterms and maxterms"], diagrams: ["nandnand", "nand_univ"] },
  { id: "cad", keys: ["cad tools", "cad flow", "design entry", "schematic capture", "logic synthesis", "functional simulation", "timing simulation", "physical design", "chip configuration", "simulation of logic circuit", "hdl vs schematic", "hierarchical design"], title: "CAD tools for logic design (design flow)", subject: "Digital electronics",
    short: "CAD tools design large logic circuits automatically. You enter the design (schematic or Verilog), the tools synthesise it into gates, simulate it, place it on a chip and check its timing.",
    points: ["Design entry: describe the circuit by drawing gates (schematic capture) or by writing code in a hardware description language such as Verilog or VHDL. Both are IEEE standard languages.", "A schematic tool uses a library of gate symbols. Smaller circuits can be saved as blocks and reused, which is hierarchical design. Schematics become hard to handle for large circuits.", "Code is plain text, can have comments, and can be reused on different chips and with different CAD tools (this is called portability).", "Synthesis turns the design into logic expressions and gates and improves it to get a better circuit. Compiling Verilog into gates is part of synthesis.", "Functional simulation checks the logic, assuming gates have zero delay. The result is a timing diagram.", "Physical design decides how the circuit is placed on the chip and how the wires run.", "Timing simulation uses the real delays of gates and wires (propagation delay). If the timing is not met, the design is changed.", "Chip configuration: for an FPGA the chip is programmed; for a custom chip it is manufactured (fabricated)."],
    steps: ["Design entry (schematic or Verilog).", "Synthesis.", "Functional simulation. If wrong, go back and change the design.", "Physical design.", "Timing simulation. If too slow, go back.", "Chip configuration or fabrication."],
    formulas: [["Propagation delay", "gate delay + wire delay"]],
    example: { title: "Which tool answers which question?", text: "Does my logic work?                 → functional simulation\nHow do I get the smallest circuit?  → synthesis\nIs it fast enough on the real chip? → timing simulation\nWhere do the gates go on the chip?  → physical design" },
    exam: "A CAD system consists of tools for design entry, logic synthesis and optimisation, simulation and physical design. Design entry may be by schematic capture or by a hardware description language such as Verilog. Synthesis converts the design into a network of logic gates. A functional simulator verifies the logic function assuming ideal gates, while a timing simulator includes the propagation delays. After the timing requirements are met the circuit is implemented on the chip by configuration or fabrication.",
    mistakes: ["Confusing functional simulation (no delays) with timing simulation (real delays).", "Skipping simulation and going straight to the chip.", "Thinking Verilog is only for simulation. It is also used for synthesis."],
    uses: [["Student FPGA projects", "Free CAD tools from chip makers take a design to an FPGA board."], ["Processor design", "Millions of gates are designed with code, not by hand."]], related: ["Digital hardware and the design process", "Hardware description languages (Verilog basics)", "Analysis and synthesis of logic circuits"], diagrams: ["cadflow", "designflow"] },
  { id: "sevenseg", keys: ["seven segment", "seven segment display", "7 segment", "7 segment display", "7 segment decoder", "bcd to seven segment", "seven segment decoder", "number display"], title: "Seven-segment display design", subject: "Digital electronics",
    short: "A seven-segment display has seven LED bars a to g. A logic circuit turns the input number into the seven outputs that light the right bars. Each output is a separate logic function.",
    points: ["A segment is lit when its output is 1.", "For a two-bit input s₁s₀ showing 0, 1, 2: a = d = e = s₀’, b = 1, c = s₁’, f = s₁’s₀’, g = s₁s₀’.", "For a BCD input x₃x₂x₁x₀ showing 0 to 9, the codes 1010 to 1111 never occur, so they are don’t-cares in the K-maps.", "Using the don’t-cares gives smaller circuits: a = x₃ + x₁ + x₂’x₀’ + x₂x₀ and e = x₂’x₀’ + x₁x₀’.", "Different outputs may need different choices for the same don’t-care cell. The best choice is decided separately for each segment.", "Common terms such as x₂’x₀’ can be shared by several outputs, which lowers cost."],
    steps: ["Write the truth table: which segments are lit for each digit.", "Draw a K-map for each segment (a, b, c, d, e, f, g).", "Mark don’t-cares for unused codes.", "Group the 1s (use don’t-cares only when they make a bigger group).", "Write each segment function and share common terms."],
    formulas: [["Segment a (BCD)", "a = x₃ + x₁ + x₂’x₀’ + x₂x₀"], ["Segment e (BCD)", "e = x₂’x₀’ + x₁x₀’"], ["Lit digits", "0: abcdef,  1: bc,  2: abdeg"]],
    example: { title: "Check segment e for digits 0 to 9", text: "e is lit for digits 0, 2, 6 and 8 only.\ne = x₂’x₀’ + x₁x₀’\n0 (0000): x₂’x₀’ = 1 ✓   2 (0010): x₂’x₀’ = 1 ✓\n6 (0110): x₁x₀’ = 1 ✓   8 (1000): x₂’x₀’ = 1 ✓\n1 (0001): both terms 0 ✓   4 (0100): 0 ✓" },
    exam: "A seven-segment display consists of seven LEDs labelled a to g. A decoder circuit converts the input code into the seven output functions which light the segments for each decimal digit. For BCD inputs the combinations 1010 to 1111 do not occur and are treated as don’t-care conditions, which are used to obtain minimum-cost expressions through Karnaugh maps.",
    mistakes: ["Forgetting that the codes 10 to 15 are don’t-cares for BCD.", "Using the same don’t-care value in every K-map. Choose per output.", "Mixing up segment letters a to g."],
    uses: [["Calculators and digital clocks", "Numbers are shown with seven-segment displays."], ["Lift floor indicators", "A decoder drives the display from the floor number."], ["Meters and counters", "Any counter that shows decimal digits uses this circuit."]], related: ["Karnaugh map", "Minimization: prime implicants, don’t-cares and cost", "Binary codes (BCD, Gray, Excess-3, ASCII)"], diagrams: ["sevenseg"] },
  { id: "func16", keys: ["16 functions", "sixteen functions", "functions of two variables", "boolean functions of two variables", "inhibition", "implication", "transfer function logic", "equivalence function", "xnor", "exclusive nor", "exclusive or", "xor", "buffer gate", "buffer", "multiple input gates", "three input xor", "odd function", "non associative", "nand not associative"], title: "Other logic operations: the 16 functions, XOR, XNOR, buffer", subject: "Digital electronics",
    short: "Two variables have 2⁴ = 16 possible Boolean functions. Only eight of them are used as standard gates: AND, OR, NOT, buffer, NAND, NOR, XOR and XNOR (equivalence).",
    points: ["With n variables there are 2ⁿ rows and so 2^(2ⁿ) functions. For n = 2 that is 16: F₀ to F₁₅.", "Two are constants (F₀ = 0, F₁₅ = 1). Four are single-variable: transfer (F₃ = x, F₅ = y) and complement (F₁₀ = y’, F₁₂ = x’). Ten use two variables.", "The ten two-variable functions: AND, OR, NAND, NOR, XOR, equivalence (XNOR), two inhibition functions (xy’ and x’y) and two implication functions (x + y’ and x’ + y).", "Inhibition and implication are not commutative or associative, so they are not used as standard gates.", "XOR: F = xy’ + x’y = x ⊕ y. It is 1 when the inputs are different. XNOR (equivalence): F = xy + x’y’ = x ⊙ y. It is 1 when the inputs are the same. They are complements of each other.", "A buffer gives F = x. It does not change the logic value; it is used only to boost the signal (power amplification). It equals two inverters in a row.", "AND, OR, XOR and XNOR are commutative and associative, so they can have more than two inputs.", "NAND and NOR are NOT associative: (x ↓ y) ↓ z ≠ x ↓ (y ↓ z). So a three-input NOR is defined as (x + y + z)’ and a three-input NAND as (xyz)’.", "A multi-input XOR is an odd function: the output is 1 when an odd number of inputs are 1. A multi-input XNOR is 1 when an even number of inputs are 0.", "NAND and NOR gates are far more popular than AND and OR because transistor circuits build them easily."],
    steps: ["Write the truth table for the two inputs.", "Read the output column as a 4-bit number: that gives the function number F₀ to F₁₅.", "Match with the name: 0001 = AND (F₁), 0110 = XOR (F₆), 0111 = OR (F₇), 1000 = NOR (F₈), 1001 = XNOR (F₉), 1110 = NAND (F₁₄)."],
    formulas: [["Number of functions", "2^(2ⁿ)"], ["XOR", "x ⊕ y = xy’ + x’y"], ["XNOR", "x ⊙ y = xy + x’y’ = (x ⊕ y)’"], ["3-input NOR", "(x + y + z)’"], ["3-input NAND", "(xyz)’"], ["3-input XOR", "x ⊕ y ⊕ z = 1 when an odd number of inputs are 1"]],
    example: { title: "Why NOR is not associative", text: "Take x = 1, y = 0, z = 0.\n(x ↓ y) ↓ z = (1 ↓ 0) ↓ 0 = 0 ↓ 0 = 1\nx ↓ (y ↓ z) = 1 ↓ (0 ↓ 0) = 1 ↓ 1 = 0\nThe answers differ, so we cannot just drop the brackets.\nThat is why a 3-input NOR is defined as (x + y + z)’.\n\nAND from NOR gates: x · y = (x’ + y’)’ — invert each input with a NOR, then NOR the results." },
    exam: "Two binary variables can form 16 Boolean functions. Of these, two are constants, four are unary (transfer and complement) and ten are binary operations: AND, OR, NAND, NOR, exclusive-OR, equivalence, inhibition and implication. Eight of them are used as standard gates. The exclusive-OR function is xy’ + x’y and the equivalence function xy + x’y’ is its complement. NAND and NOR are commutative but not associative, so multiple-input NAND and NOR gates are defined as complemented AND and OR gates. The exclusive-OR with more than two inputs is an odd function.",
    mistakes: ["Calling the buffer a logic operation. It only strengthens the signal.", "Using (x ↓ y) ↓ z as a 3-input NOR. Use (x + y + z)’.", "Thinking XOR gives 1 when both inputs are 1. It gives 0."],
    uses: [["Parity and error checking", "XOR gates compute whether the number of 1s is odd or even."], ["Adders", "The sum bit of a half adder is an XOR."], ["Signal driving", "A buffer lets one output drive many gate inputs."]], related: ["Logic gates", "Parity and error detection", "Building circuits with only NAND or only NOR gates"], diagrams: ["func16", "gates"] },
  { id: "polarity", keys: ["positive logic", "negative logic", "polarity indicator", "h and l levels", "high and low levels", "logic levels voltage", "dual function logic", "7400 positive logic", "ttl voltage levels", "ecl voltage levels", "cmos voltage levels"], title: "Positive and negative logic; H and L levels", subject: "Digital electronics",
    short: "A gate really works with two voltage levels, H (high) and L (low). Which one means logic 1 is our choice. Positive logic: H = 1. Negative logic: L = 1. The same gate becomes NAND in one and NOR in the other.",
    points: ["Data sheets describe gates with H and L, not with 1 and 0.", "Positive logic: the higher level H is 1, the lower level L is 0. Negative logic: L is 1 and H is 0. Positive and negative here do not mean the polarity of the voltage.", "Typical levels from the textbook: TTL H = 3.5 V, L = 0.2 V (supply 5 V). ECL H = −0.8 V, L = −1.8 V (both negative; the higher one is H). CMOS H = V_DD (3 to 15 V supply), L = 0 V.", "A 7400 gate has the H/L table: LL→H, LH→H, HL→H, HH→L. In positive logic this is NAND. In negative logic the table reads 11→0, 10→0, 01→0, 00→1, which is NOR.", "So a positive-logic NAND is the same physical gate as a negative-logic NOR. Likewise a positive-logic NOR is a negative-logic NAND, AND ↔ OR, and XOR ↔ XNOR.", "Changing from positive to negative logic swaps all 0s and 1s at inputs and output. That takes the dual of the function: every AND becomes OR and vice versa.", "A small triangle on a terminal is the polarity indicator: it means negative logic is used there. It is different from the small circle, which means complement."],
    steps: ["Write the gate’s truth table in H and L.", "Positive logic: put H = 1, L = 0 and read the function.", "Negative logic: put L = 1, H = 0 and read the function.", "The second function is the dual of the first."],
    formulas: [["Positive logic", "H = 1, L = 0"], ["Negative logic", "L = 1, H = 0"], ["Effect on function", "NAND ↔ NOR, AND ↔ OR, XOR ↔ XNOR"]],
    example: { title: "One chip, two names", text: "Gate table:  x y → z\nL L → H\nL H → H\nH L → H\nH H → L\n\nPositive logic (H=1): 00→1, 01→1, 10→1, 11→0 = NAND\nNegative logic (L=1): 11→0, 10→0, 01→0, 00→1 = NOR" },
    exam: "In positive logic the higher signal level H represents logic-1 and the lower level L represents logic-0; in negative logic the assignment is reversed. A physical gate that performs the NAND function in positive logic performs the NOR function in negative logic. The change of logic assignment produces the dual of the function. A polarity indicator (small triangle) shows that negative logic is assumed at a terminal.",
    mistakes: ["Thinking positive logic means a positive voltage. It only means H is called 1.", "Mixing up the polarity indicator (triangle) with the complement bubble (circle).", "Forgetting that changing the logic type changes AND to OR, not just the symbol."],
    uses: [["Reading data sheets", "Chip makers give H and L tables; you decide the logic."], ["Mixed systems", "Interfacing parts that use different assignments needs careful symbol choice."]], related: ["Logic gates", "Logic families (TTL, CMOS, ECL)", "Other logic operations: the 16 functions, XOR, XNOR, buffer"], diagrams: ["polarity"] },
  { id: "canonical", keys: ["canonical forms", "standard forms", "complement of a function", "complement of function", "generalized de morgan", "generalised de morgan", "convert sop to pos", "sum of minterms to product of maxterms", "expand to minterms", "missing variables", "sigma and pi", "dual and complement"], title: "Complement of a function and canonical forms", subject: "Digital electronics",
    short: "Any Boolean function can be written as a sum of minterms (Σ) or a product of maxterms (Π). The complement of a function is found with generalised De Morgan, or by taking the dual and complementing each literal.",
    points: ["Complement F’: swap 0s and 1s in the truth table, or use De Morgan’s theorem repeatedly.", "Generalised De Morgan: (A + B + C + … + F)’ = A’B’C’…F’ and (ABC…F)’ = A’ + B’ + C’ + … + F’. In words: swap AND and OR and complement every literal.", "Quicker method: take the dual of F (swap AND/OR and 0/1) and then complement each literal.", "n variables give 2ⁿ minterms and 2ⁿ maxterms. A minterm is a product of all variables (primed if the bit is 0). A maxterm is a sum of all variables (primed if the bit is 1). Mⱼ = mⱼ’.", "Sum of minterms: expand every term until it contains all the variables, by ANDing with (x + x’), then remove repeated minterms. Σ lists the minterms.", "Product of maxterms: put the function into OR terms with the distributive law x + yz = (x + y)(x + z), then OR each missing variable with xx’. Π lists the maxterms.", "Converting between the two forms: swap Σ and Π and list the numbers that were missing.", "Standard forms: sum of products (AND terms ORed) and product of sums (OR terms ANDed). The terms may have any number of literals. A form like (AB + CD)(A’B’ + C’D’) is nonstandard; multiply out to make it standard.", "The number of different functions of n variables is 2^(2ⁿ)."],
    steps: ["For Σ: write the missing variables as (x + x’) factors and multiply out.", "Write each product as a minterm number.", "Remove repeats and list the numbers in order.", "For Π: use the minterm numbers that are NOT in the list."],
    formulas: [["Complement", "F’ = dual of F with every literal complemented"], ["Σ to Π", "F = Σ(list) = Π(missing numbers)"], ["Maxterm", "Mⱼ = (mⱼ)’"], ["Number of terms", "2ⁿ minterms (maxterms)"]],
    example: { title: "F = A + B’C as sum of minterms, and F = xy + x’z as product of maxterms", text: "A = AB + AB’ = ABC + ABC’ + AB’C + AB’C’\nB’C = AB’C + A’B’C\nF = A’B’C + AB’C’ + AB’C + ABC’ + ABC = Σ(1, 4, 5, 6, 7)\nComplement: F’ = Σ(0, 2, 3), so F = Π(0, 2, 3)\n\nF = xy + x’z = (x’ + y)(x + z)(y + z)\nAfter adding missing variables:\nF = (x + y + z)(x + y’ + z)(x’ + y + z)(x’ + y + z’) = Π(0, 2, 4, 5)\n\nComplement of F = x’yz’ + x’y’z:\nF’ = (x + y’ + z)(x + y + z’)" },
    exam: "A minterm is an AND term containing all the variables of the function in complemented or uncomplemented form. A maxterm is an OR term containing all the variables. Any Boolean function can be expressed as a sum of minterms or as a product of maxterms, which are called canonical forms. The complement of a function is obtained by interchanging AND and OR operators and complementing each literal. To convert from one canonical form to the other, interchange the symbols Σ and Π and list the numbers missing from the original form.",
    mistakes: ["Forgetting to remove repeated minterms after expanding.", "Converting Σ to Π without taking the missing numbers.", "Complementing only the variables and not swapping AND and OR."],
    uses: [["Programmable logic", "Functions are stored as lists of minterms."], ["Checking answers", "Σ and Π forms of the same function must have complementary lists."]], related: ["SOP, POS, minterms and maxterms", "Boolean algebra", "Karnaugh map"], diagrams: [] },
  { id: "huntington", keys: ["huntington postulates", "postulates of boolean algebra", "axioms of boolean algebra", "axiomatic definition", "two valued boolean algebra", "switching algebra", "boolean algebra vs ordinary algebra", "algebraic structure", "closure", "identity element", "boole shannon"], title: "Boolean algebra: postulates and how it differs from ordinary algebra", subject: "Digital electronics",
    short: "Boolean algebra is defined by a set B with two operators + and · that follow the Huntington postulates. The two-valued case, B = {0, 1}, is called switching algebra and is the maths of logic circuits.",
    points: ["History: George Boole introduced it in 1854 to treat logic mathematically. C. E. Shannon (1938) showed that it describes circuits of two-state switches, and called it switching algebra. E. V. Huntington formulated the postulates in 1904.", "Huntington postulates: closure for + and ·; identity 0 for + and 1 for ·; commutative for both; · is distributive over + and + is distributive over ·; every x has a complement x’ with x + x’ = 1 and x·x’ = 0; there are at least two different elements.", "In two-valued Boolean algebra B = {0, 1}, + is OR, · is AND and ’ is NOT. Each postulate can be checked with the operator tables or a truth table.", "Differences from ordinary algebra: (1) the associative law is not a postulate but can be proved; (2) x + yz = (x + y)(x + z) is true, but not in ordinary algebra; (3) there are no additive or multiplicative inverses, so no subtraction or division; (4) there is a complement operator; (5) the set has only two elements.", "Variables like x, y, z are symbols standing for 0 or 1, just as in ordinary algebra they stand for numbers.", "Duality: every postulate comes in pairs; swapping + with · and 0 with 1 turns one into the other. So any theorem you prove also gives its dual theorem for free.", "Operator precedence: parentheses, then NOT, then AND, then OR.", "Core theorems: x + x = x, x·x = x, x + 1 = 1, x·0 = 0, (x’)’ = x, absorption x + xy = x and x(x + y) = x, De Morgan (x + y)’ = x’y’ and (xy)’ = x’ + y’."],
    steps: ["Pick the theorem to prove.", "Start from one side and use postulates one at a time (each step must name the rule).", "Prove the dual by changing + ↔ · and 0 ↔ 1 in every step."],
    formulas: [["Postulate 5", "x + x’ = 1,  x · x’ = 0"], ["Distributive (b)", "x + yz = (x + y)(x + z)"], ["Idempotent proof", "x + x = (x + x)·1 = (x + x)(x + x’) = x + xx’ = x + 0 = x"], ["Absorption proof", "x + xy = x·1 + xy = x(1 + y) = x·1 = x"]],
    example: { title: "Prove x + x = x from the postulates", text: "x + x = (x + x)·1        postulate 2(b)\n      = (x + x)(x + x’)  postulate 5(a)\n      = x + xx’          postulate 4(b)\n      = x + 0            postulate 5(b)\n      = x                postulate 2(a)\n\nDual: x · x = x (every step swaps + and ·, 0 and 1)." },
    exam: "Boolean algebra is an algebraic structure defined on a set of elements B together with two binary operators + and · which satisfy the Huntington postulates: closure, identity elements 0 and 1, commutativity, distributivity of each operator over the other, existence of a complement for every element, and at least two distinct elements. The two-valued Boolean algebra with B = {0, 1} is called switching algebra. It differs from ordinary algebra in that + is distributive over ·, there are no inverses, and a complement operator exists.",
    mistakes: ["Using ordinary algebra tricks such as subtracting or dividing both sides.", "Assuming x + x = 2x. In Boolean algebra x + x = x.", "Forgetting to state the postulate used at each step in a proof."],
    uses: [["Proof questions in exams", "Theorems must be proved step by step from the postulates."], ["Foundation of computing", "Every digital circuit is a Boolean function."]], related: ["Boolean algebra", "Venn diagrams and proving Boolean identities", "Logic gates"], diagrams: ["bvenn"] },
  { id: "twolevel", keys: ["two level implementation", "two level", "nand rules", "nor implementation rules", "and or invert", "aoi", "or and invert", "oai", "wired and", "wired or", "wired logic", "open collector", "degenerate forms", "nondegenerate forms", "and nor form", "nand and form", "or nand form", "nor or form", "invert or symbol", "and invert symbol"], title: "Two-level forms: NAND, NOR, AND–OR–INVERT and wired logic", subject: "Digital electronics",
    short: "Any function in standard form needs only two levels of gates. With NAND or NOR gates there are eight useful two-level forms. To choose the right one, simplify either F or its complement F′ and follow the rules table.",
    points: ["NAND has two symbols: AND-invert, and invert-OR (an OR symbol with circles on the inputs). NOR also has two: OR-invert, and invert-AND. A small circle means complement; two circles on one wire cancel.", "NAND rule: (1) simplify F as a sum of products; (2) draw one NAND gate for each product term that has at least two literals; (3) draw one NAND gate in the second level; (4) a term with a single literal needs an inverter, or you can feed its complement straight to the second-level gate.", "NOR rule: the dual. Simplify F as a product of sums; the first-level NOR gates are the sum terms; one NOR gate in the second level.", "If you combine the 0s of a K-map you get F′ as SOP. A two-level NAND circuit then gives F′ and you need a one-input NAND (inverter) as a third level to get F.", "Rules table: (a) F as SOP → NAND, 2 levels. (b) F′ as SOP (from the 0s) → NAND, 3 levels. (c) F as POS → NOR, 2 levels. (d) F′ as POS → NOR, 3 levels.", "With four gate types (AND, OR, NAND, NOR) in two levels there are 16 combinations. Eight are degenerate (they collapse to a single AND or OR, like AND–AND) and eight are nondegenerate: AND–OR, NAND–NAND, NOR–OR, OR–NAND (SOP-type) and OR–AND, NOR–NOR, NAND–AND, AND–NOR (POS-type).", "AND–OR–INVERT (AND–NOR or NAND–AND): F = (AB + CD + E)′. Simplify F′ as SOP, then the INVERT gives F.", "OR–AND–INVERT (OR–NAND or NOR–OR): F = ((A + B)(C + D)E)′. Simplify F′ as POS.", "Wired logic: some gates may have outputs tied together. Open-collector TTL NAND gates wired together give wired-AND: F = (AB)′·(CD)′ = (AB + CD)′ (AND–OR–INVERT). ECL NOR gates tied together give wired-OR: F = ((A + B)(C + D))′ (OR–AND–INVERT). The wire is not a real gate."],
    steps: ["Pick the form and decide whether to simplify F or F′.", "Use the K-map: combine 1s for SOP of F, combine 0s for SOP of F′.", "For POS take the complement of the SOP you got from the other set.", "Draw first-level gates for each term and one second-level gate.", "Add an inverter for single-literal terms or complement the input."],
    formulas: [["NAND–NAND", "F = ((AB)′(CD)′E′)′ = AB + CD + E"], ["AND–NOR", "F = (AB + CD + E)′"], ["OR–NAND", "F = ((A + B)(C + D)E)′"], ["Wired-AND", "F = (AB)′ · (CD)′ = (AB + CD)′"]],
    example: { title: "F = Σ(0, 6) four ways", text: "Map: two 1s that cannot be combined.\nSOP: F = x′y′z′ + xyz′ → two-level NAND.\nCombine the 0s instead: F′ = x′y + xy′ + z\nAs AND–OR–INVERT: F = (x′y + xy′ + z)′ → AND–NOR or NAND–AND.\nPOS from complement of SOP: F = (x + y′)(x′ + y)z′ → NOR–NOR (the z′ term goes straight in if z′ is available).\nThe 1-input gate for a single literal is dropped when the input is already available in the right form." },
    exam: "Two-level implementations with NAND and NOR gates are obtained by simplifying the function in sum-of-products form (NAND–NAND) or product-of-sums form (NOR–NOR). Eight non-degenerate two-level forms exist: AND–OR, OR–AND, NAND–NAND, NOR–NOR, NOR–OR, NAND–AND, OR–NAND and AND–NOR. The AND–NOR and NAND–AND forms perform the AND–OR–INVERT function and the OR–NAND and NOR–OR forms perform OR–AND–INVERT; for these the complement of the function is simplified. Wired logic connects gate outputs together: open-collector TTL gives wired-AND and ECL NOR gives wired-OR.",
    mistakes: ["Forgetting the inverter (or complemented input) for a single-literal term in NAND–NAND.", "Simplifying F when the INVERT forms need F′.", "Calling wired-AND a physical gate. It is only a wire connection."],
    uses: [["IC design", "NAND/NOR cells are the cheapest, so tools map logic into them."], ["Exam circuits", "“Draw using only NAND gates” is a standard 5–8 mark question."]], related: ["Building circuits with only NAND or only NOR gates", "Complement of a function and canonical forms", "Minimization: prime implicants, don’t-cares and cost"], diagrams: ["aoi", "nandnand"] },
  { id: "dflow", keys: ["digital hardware", "digital design process", "design process", "design flow", "types of chips", "standard chips", "custom chips", "asic", "application specific integrated circuit", "moores law", "moore s law", "logic circuits introduction", "computer aided design", "structure of a computer"], title: "Digital hardware and the design process", subject: "Digital electronics",
    short: "Digital hardware is any product built from logic circuits. Designers build logic circuits with standard chips, programmable logic devices (such as FPGAs) or custom chips (ASICs), and follow a design process that goes from specifications to a tested prototype.",
    points: ["Logic circuits are made of transistors on an integrated circuit (IC). A chip can hold billions of transistors. Moore’s law says the number of transistors on a chip roughly doubles about every two years.", "Standard chips have a fixed function and only a small circuit inside (usually fewer than 100 transistors), such as the 74-series chips. Many of them are wired together on a printed circuit board (PCB). They waste board space and cannot be changed.", "Programmable logic devices (PLDs) contain programmable switches, so the user sets their function after manufacture. The FPGA (field-programmable gate array) is the most common PLD. No factory delay is involved, so it is good for prototypes and small production.", "Custom (or semi-custom) chips, called ASICs, are designed from scratch and made by a chip factory. They give the best speed and the smallest area, but the design cost is high and manufacturing takes months. The cost per chip becomes low only in large volumes.", "A computer is built in layers: the case holds a motherboard (PCB) and a power supply, the motherboard carries chips, each chip contains sub-circuits, each sub-circuit is a network of logic gates, and each gate is made of transistors.", "Design process: define the specifications, make an initial design, simulate it with CAD tools, redesign if it is wrong, build a prototype, test it, and fix minor errors or redesign if the prototype fails."],
    steps: ["Define the specifications: what the product must do, how fast, how big and at what cost.", "Make the initial design. This step needs human skill and experience.", "Simulate the design with CAD tools and compare the result with the specifications.", "If the simulation shows errors, redesign and simulate again.", "Build a prototype (for example on an FPGA board).", "Test the prototype. Correct small errors directly; redesign for large errors.", "When the tests pass, the product is finished and can go into production."],
    formulas: [["Moore’s law", "N(t) ≈ N₀ × 2^(t / 2 years)"], ["Logic levels", "0 ≈ 0 V (ground),  1 ≈ supply voltage"]],
    example: { title: "Which chip type fits which job?", text: "A few simple gates on a small board  → standard chips\nA new idea or a small batch of 100 boards → FPGA (no factory delay)\nA phone processor sold in millions → ASIC (best speed and cost per chip in volume)" },
    exam: "Digital hardware consists of logic circuits implemented on integrated circuit chips. The three ways of implementing logic circuits are standard chips, programmable logic devices (PLDs, mainly FPGAs) and custom-designed chips (ASICs). Standard chips have fixed functions, PLDs are programmed by the user, and custom chips give the best performance but need a long and costly manufacturing process. The design process consists of specification, initial design, simulation, prototype implementation and testing, with redesign loops when errors are found.",
    mistakes: ["Saying an FPGA is made for one function at the factory. It is programmed by the user.", "Mixing up ASIC (factory-made, fixed) and FPGA (user-programmed).", "Skipping simulation and going straight to the prototype."],
    uses: [["Phones and laptops", "Processors are custom chips made in very large numbers."], ["Student projects and prototypes", "FPGA boards let you test a design without a factory."], ["Industrial controllers", "A mix of standard chips and FPGAs controls machines."]], related: ["Number systems and conversions", "ROM, PLA and PAL (programmable logic)", "Hardware description languages (Verilog basics)"], diagrams: ["layers", "chiptypes", "moore", "designflow"] },
);
const DMAP2 = {};
const norm = (t) => String(t || "").toLowerCase().replace(/[-_/]/g, " ").replace(/[^a-z0-9\s+]/g, " ").replace(/\s+/g, " ").trim();
// Returns the best matching pack for a question, or null. Longer key phrases win.
export function packFind(q) {
  const t = " " + norm(q) + " "; let best = null, bl = 0;
  for (const p of PACKS) for (const k of p.keys) { const kk = norm(k); if (t.includes(" " + kk + " ") && kk.length > bl) { best = p; bl = kk.length; } }
  return best;
}

export function packScore(q) {
  const t = " " + norm(q) + " "; let best = null, bl = 0;
  for (const p of PACKS) for (const k of p.keys) { const kk = norm(k); if (t.includes(" " + kk + " ") && kk.length > bl) { best = p; bl = kk.length; } }
  return { p: best, len: bl };
}
